pub async fn gallery_list(
    State(state): State<Arc<AppState>>,
) -> impl IntoResponse {
    let _lock = state.gemma_gallery_lock.lock().await;
    match store::read_gallery() {
        Ok(g) => Json(g).into_response(),
        Err(e) => {
            warn!("gallery_list: {e}");
            (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response()
        }
    }
}

// ── POST /api/gemma/gallery ───────────────────────────────────────────────────

pub async fn gallery_append(
    State(state): State<Arc<AppState>>,
    Json(new_specs): Json<GalleryAppendRequest>,
) -> impl IntoResponse {
    let _lock = state.gemma_gallery_lock.lock().await;
    let mut gallery = match store::read_gallery() {
        Ok(g) => g,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };

    for spec in &new_specs {
        if gallery.specs.iter().any(|s| s.id == spec.id) {
            return (StatusCode::CONFLICT, format!("duplicate id: {}", spec.id)).into_response();
        }
        if gallery.specs.iter().any(|s| s.signature == spec.signature) {
            return (
                StatusCode::CONFLICT,
                format!("duplicate signature: {}", spec.signature),
            )
            .into_response();
        }
    }

    gallery.specs.extend(new_specs);
    gallery.specs.sort_by(|a, b| b.created_at.cmp(&a.created_at));

    match store::write_gallery(&gallery) {
        Ok(()) => StatusCode::CREATED.into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

// ── DELETE /api/gemma/gallery/:id ────────────────────────────────────────────

pub async fn gallery_delete(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    let _lock = state.gemma_gallery_lock.lock().await;
    let mut gallery = match store::read_gallery() {
        Ok(g) => g,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };

    let before = gallery.specs.len();
    gallery.specs.retain(|s| s.id != id);
    if gallery.specs.len() == before {
        return StatusCode::NOT_FOUND.into_response();
    }

    match store::write_gallery(&gallery) {
        Ok(()) => StatusCode::NO_CONTENT.into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

