// ── POST /api/gemma/catalog/promote/:id ──────────────────────────────────────

pub async fn catalog_promote(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    // Always acquire gallery lock first, then catalog — consistent order prevents deadlock.
    let _glock = state.gemma_gallery_lock.lock().await;
    let _clock = state.gemma_catalog_lock.lock().await;

    let mut gallery = match store::read_gallery() {
        Ok(g) => g,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };
    let mut catalog = match store::read_catalog() {
        Ok(c) => c,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };

    let idx = gallery.specs.iter().position(|s| s.id == id);
    let Some(idx) = idx else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let spec = gallery.specs.remove(idx);
    catalog.entries.push(GemmaCatalogEntry {
        base: spec,
        promoted_at: now_secs(),
        label: None,
    });

    if let Err(e) = store::write_gallery(&gallery) {
        return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response();
    }
    match store::write_catalog(&catalog) {
        Ok(()) => StatusCode::OK.into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

// ── DELETE /api/gemma/catalog/:id ────────────────────────────────────────────

pub async fn catalog_delete(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    let _lock = state.gemma_catalog_lock.lock().await;
    let mut catalog = match store::read_catalog() {
        Ok(c) => c,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };

    let before = catalog.entries.len();
    catalog.entries.retain(|e| e.base.id != id);
    if catalog.entries.len() == before {
        return StatusCode::NOT_FOUND.into_response();
    }

    match store::write_catalog(&catalog) {
        Ok(()) => StatusCode::NO_CONTENT.into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

// ── PATCH /api/gemma/catalog/:id ─────────────────────────────────────────────

pub async fn catalog_update(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
    Json(req): Json<CatalogUpdateRequest>,
) -> impl IntoResponse {
    let _lock = state.gemma_catalog_lock.lock().await;
    let mut catalog = match store::read_catalog() {
        Ok(c) => c,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };

    let entry = catalog.entries.iter_mut().find(|e| e.base.id == id);
    let Some(entry) = entry else {
        return StatusCode::NOT_FOUND.into_response();
    };

    if let Some(label) = req.label {
        entry.label = Some(label);
    }
    if let Some(tags) = req.tags {
        entry.base.tags = tags;
    }

    match store::write_catalog(&catalog) {
        Ok(()) => StatusCode::OK.into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

