//! Atomic read/write helpers for the gallery and catalog SHM JSON files.

use super::types::{GemmaCatalog, GemmaSpecGallery};
use anyhow::{Context, Result};
use std::fs;
use std::io::Write;
use std::path::Path;

pub const GALLERY_PATH: &str = "/dev/shm/gemma-ui-specs.json";
pub const CATALOG_PATH: &str = "/dev/shm/gemma-ui-catalog.json";
const GALLERY_MAX: usize = 500;

// ── Gallery ─────────────────────────────────────────────────────────────────

pub fn read_gallery() -> Result<GemmaSpecGallery> {
    match fs::read(GALLERY_PATH) {
        Ok(bytes) => serde_json::from_slice(&bytes)
            .with_context(|| format!("malformed gallery JSON at {GALLERY_PATH}")),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(GemmaSpecGallery::default()),
        Err(e) => Err(e).with_context(|| format!("read {GALLERY_PATH}")),
    }
}

pub fn write_gallery(gallery: &GemmaSpecGallery) -> Result<()> {
    let mut g = gallery.clone();
    // Keep newest GALLERY_MAX entries.
    if g.specs.len() > GALLERY_MAX {
        g.specs.sort_by(|a, b| b.created_at.cmp(&a.created_at));
        g.specs.truncate(GALLERY_MAX);
    }
    atomic_write(GALLERY_PATH, &serde_json::to_vec_pretty(&g)?)
}

// ── Catalog ──────────────────────────────────────────────────────────────────

pub fn read_catalog() -> Result<GemmaCatalog> {
    match fs::read(CATALOG_PATH) {
        Ok(bytes) => serde_json::from_slice(&bytes)
            .with_context(|| format!("malformed catalog JSON at {CATALOG_PATH}")),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(GemmaCatalog::default()),
        Err(e) => Err(e).with_context(|| format!("read {CATALOG_PATH}")),
    }
}

pub fn write_catalog(catalog: &GemmaCatalog) -> Result<()> {
    atomic_write(CATALOG_PATH, &serde_json::to_vec_pretty(catalog)?)
}

// ── Shared ───────────────────────────────────────────────────────────────────

fn atomic_write(path: &str, data: &[u8]) -> Result<()> {
    let tmp = format!("{path}.tmp");
    let mut f =
        fs::File::create(&tmp).with_context(|| format!("create tmp {tmp}"))?;
    f.write_all(data).with_context(|| format!("write {tmp}"))?;
    f.sync_data().with_context(|| format!("sync {tmp}"))?;
    drop(f);
    fs::rename(&tmp, Path::new(path))
        .with_context(|| format!("rename {tmp} → {path}"))
}

//! Router configuration for op-web

use axum::{
    routing::{get, post},
    Router,
};
use std::sync::Arc;

use crate::routes;
use crate::state::AppState;
use crate::websocket::handle_websocket;

/// Web service router builder
pub struct WebServiceRouter;

impl WebServiceRouter {
    /// Create a new router with all routes
    pub fn new() -> Self {
        Self
    }
}

/// Create the main application router
pub fn create_router(state: Arc<AppState>, static_dir: Option<String>) -> Router {
    let router = Router::new()
        // Health check
        .route("/api/health", get(routes::health_check))
        // LLM routes
        .route("/api/schema/catalog", get(crate::handlers::schema::schema_catalog_raw_handler))
        .route("/api/schema/catalog/detail", get(crate::handlers::schema::schema_catalog_handler))
        .route("/api/llm/status", get(routes::llm::get_llm_status))
        .route(
            "/api/llm/providers",
            get(crate::handlers::llm::list_providers_handler),
        )
        .route("/api/llm/models", get(routes::llm::get_models))
        // Chat routes
        .route("/api/chat", post(routes::chat::chat_message))
        // Tool routes
        .route("/api/tools", get(routes::tools::list_tools))
        .route("/api/tools/:name", get(routes::tools::get_tool))
        .route(
            "/api/tools/:name/execute",
            post(routes::tools::execute_tool),
        )
        // WebSocket
        .route("/ws", get(handle_websocket))
        .with_state(state);

    // No SPA fallback: API/WebSocket only. Unmatched routes return 404.
    let _ = static_dir;
    router
}

/// Create WebSocket-only router (for composition)
pub fn create_websocket_router(state: Arc<AppState>) -> Router {
    Router::new()
        .route("/ws", get(handle_websocket))
        .with_state(state)
}

