import { useState } from "react";
import { cn } from "@/lib/utils";

interface JsonRendererProps {
  data: unknown;
  defaultMode?: "tree" | "raw";
  maxDepth?: number;
  className?: string;
}

export function JsonRenderer({ data, defaultMode = "tree", maxDepth = 6, className }: JsonRendererProps) {
  const [mode, setMode] = useState<"tree" | "raw">(defaultMode);

  const handleCopy = () => {
    navigator.clipboard.writeText(JSON.stringify(data, null, 2));
  };

  return (
    <div className={cn("rounded-lg border border-border bg-card overflow-hidden", className)}>
      <div className="flex items-center justify-between border-b border-border px-3 py-1.5">
        <span className="text-[11px] font-medium text-muted-foreground uppercase tracking-wider">Inspector</span>
        <div className="flex gap-1">
          {(["tree", "raw"] as const).map((m) => (
            <button key={m} onClick={() => setMode(m)} className={cn(
              "px-2 py-0.5 text-xs rounded-md transition-colors",
              mode === m ? "bg-primary/15 text-primary font-medium" : "text-muted-foreground hover:text-foreground"
            )}>{m === "tree" ? "Tree" : "Raw"}</button>
          ))}
          <button onClick={handleCopy} className="px-2 py-0.5 text-xs rounded-md text-muted-foreground hover:text-foreground transition-colors">Copy</button>
        </div>
      </div>
      <div className="p-3 overflow-auto max-h-[500px] font-mono text-xs leading-relaxed">
        {mode === "raw" ? (
          <pre className="text-foreground whitespace-pre-wrap break-all">{JSON.stringify(data, null, 2)}</pre>
        ) : (
          <JsonTree data={data} depth={0} maxDepth={maxDepth} />
        )}
      </div>
    </div>
  );
}

function JsonTree({ data, depth, maxDepth, label }: { data: unknown; depth: number; maxDepth: number; label?: string }) {
  const [collapsed, setCollapsed] = useState(depth > 2);

  if (data === null || data === undefined) {
    return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className="text-muted-foreground italic">null</span></div>;
  }
  if (typeof data === "boolean") {
    return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className={data ? "text-ok" : "text-danger"}>{String(data)}</span></div>;
  }
  if (typeof data === "number") {
    return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className="text-info">{data}</span></div>;
  }
  if (typeof data === "string") {
    return <div className="flex items-baseline gap-1.5 min-w-0">{label && <span className="text-muted-foreground shrink-0">{label}:</span>}<span className="text-warn break-all">"{data}"</span></div>;
  }

  if (Array.isArray(data)) {
    if (depth >= maxDepth) return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className="text-muted-foreground">[{data.length} items]</span></div>;
    return (
      <div>
        <button onClick={() => setCollapsed(!collapsed)} className="flex items-baseline gap-1.5 hover:text-foreground text-muted-foreground">
          <span className="text-[10px]">{collapsed ? "▸" : "▾"}</span>
          {label && <span>{label}:</span>}
          <span className="text-muted-foreground text-[11px]">[{data.length}]</span>
        </button>
        {!collapsed && <div className="ml-4 border-l border-border/50 pl-3 mt-0.5 space-y-0.5">{data.map((item, i) => <JsonTree key={i} data={item} depth={depth + 1} maxDepth={maxDepth} label={String(i)} />)}</div>}
      </div>
    );
  }

  if (typeof data === "object") {
    const entries = Object.entries(data as Record<string, unknown>);
    if (depth >= maxDepth) return <div className="flex items-baseline gap-1.5">{label && <span className="text-muted-foreground">{label}:</span>}<span className="text-muted-foreground">{`{${entries.length} keys}`}</span></div>;
    return (
      <div>
        <button onClick={() => setCollapsed(!collapsed)} className="flex items-baseline gap-1.5 hover:text-foreground text-muted-foreground">
          <span className="text-[10px]">{collapsed ? "▸" : "▾"}</span>
          {label && <span>{label}:</span>}
          <span className="text-muted-foreground text-[11px]">{`{${entries.length}}`}</span>
        </button>
        {!collapsed && <div className="ml-4 border-l border-border/50 pl-3 mt-0.5 space-y-0.5">{entries.map(([key, val]) => <JsonTree key={key} data={val} depth={depth + 1} maxDepth={maxDepth} label={key} />)}</div>}
      </div>
    );
  }

  return <span className="text-foreground">{String(data)}</span>;
}

export { JsonTree };

import { useState, useRef, useEffect, useCallback } from "react";
import { Callout } from "@/components/shell/Primitives";
import { JsonRenderer } from "@/components/json/JsonRenderer";
import { MessageBubble, type LocalMessage } from "@/components/chat/MessageBubble";
import { SystemPromptEditor } from "@/components/chat/SystemPromptEditor";
import { LiveLogPanel } from "@/components/chat/LiveLogPanel";
import { useEventStore } from "@/stores/event-store";
import { assistantService } from "@/grpc/client";
import { cn } from "@/lib/utils";
import { X, Maximize2, MessageSquare, FileText, ScrollText } from "lucide-react";

type ChatTab = "chat" | "system-prompt" | "live-log";

/** Coerce arbitrary backend content into a renderable string. */
function normalizeContent(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return String(value);
  }
}

function mapBackendRole(role: string): LocalMessage["role"] {
  if (role === "user" || role === "assistant" || role === "system" || role === "tool") return role;
  return "system";
}

function makeId(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

export default function ChatPage() {
  const { connected } = useEventStore();
  const [activeTab, setActiveTab] = useState<ChatTab>("chat");
  const [messages, setMessages] = useState<LocalMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [sessionKey, setSessionKey] = useState("default");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarContent, setSidebarContent] = useState<unknown>(null);
  const [focusMode, setFocusMode] = useState(false);
  const [sending, setSending] = useState(false);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const threadRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = useCallback(() => {
    threadRef.current?.scrollTo({ top: threadRef.current.scrollHeight, behavior: "smooth" });
  }, []);

  useEffect(() => { scrollToBottom(); }, [messages, scrollToBottom]);

  /** Load history for the active session from the backend. */
  const loadHistory = useCallback(async (sid: string) => {
    setLoadingHistory(true);
    setError(null);
    try {
      const resp = await assistantService.getSessionHistory({ sessionId: sid });
      const mapped: LocalMessage[] = (resp.messages ?? []).map((m, i) => ({
        id: `hist-${sid}-${i}`,
        role: mapBackendRole(m.role),
        content: normalizeContent(m.content),
        timestamp: m.timestamp ? m.timestamp.seconds * 1000 : Date.now(),
      }));
      setMessages(
        mapped.length > 0
          ? mapped
          : [{ id: makeId("sys"), role: "system", content: `Session "${sid}" ready.`, timestamp: Date.now() }],
      );
    } catch (err) {
      setError((err as Error).message);
      setMessages([{ id: makeId("sys"), role: "system", content: `Failed to load history: ${(err as Error).message}`, timestamp: Date.now() }]);
    } finally {
      setLoadingHistory(false);
    }
  }, []);

  // Load history whenever session changes
  useEffect(() => {
    void loadHistory(sessionKey);
  }, [sessionKey, loadHistory]);

  const handleSend = async () => {
    const text = draft.trim();
    if (!text || sending) return;

    const userMsg: LocalMessage = {
      id: makeId("msg"),
      role: "user",
      content: text,
      timestamp: Date.now(),
    };
    setMessages((prev) => [...prev, userMsg]);
    setDraft("");
    setSending(true);
    setError(null);

    try {
      const resp = await assistantService.sendMessage({
        sessionId: sessionKey,
        content: text
      });
      // Handle the gRPC response directly
      const assistantMsg: LocalMessage = {
        id: makeId("resp"),
        role: "assistant",
        content: normalizeContent(resp.content),
        timestamp: resp.timestamp ? resp.timestamp.seconds * 1000 : Date.now(),
      };
      setMessages((prev) => [...prev, assistantMsg]);
    } catch (err) {
      const msg = (err as Error).message;
      setError(msg);
      setMessages((prev) => [
        ...prev,
        { id: makeId("err"), role: "system", content: `Request failed: ${msg}`, timestamp: Date.now() },
      ]);
    } finally {
      setSending(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      void handleSend();
    }
  };

  const handleNewSession = async () => {
    setError(null);
    try {
      const session = await assistantService.createSession({ agentId: "default" });
      setSessionKey(session.id);
      // history load happens via the useEffect on sessionKey change
    } catch (err) {
      const msg = (err as Error).message;
      setError(msg);
      setMessages((prev) => [
        ...prev,
        { id: makeId("err"), role: "system", content: `Failed to create session: ${msg}`, timestamp: Date.now() },
      ]);
    }
  };

  const openInSidebar = (data: unknown) => {
    setSidebarContent(data);
    setSidebarOpen(true);
  };

  const tabs: { id: ChatTab; label: string; icon: React.ReactNode }[] = [
    { id: "chat", label: "Chat", icon: <MessageSquare className="h-3.5 w-3.5" /> },
    { id: "live-log", label: "Live Log", icon: <ScrollText className="h-3.5 w-3.5" /> },
    { id: "system-prompt", label: "System Prompt", icon: <FileText className="h-3.5 w-3.5" /> },
  ];

  return (
    <div className="flex flex-col h-full">
      {/* Header with tabs */}
      {!focusMode && (
        <div className="border-b border-border shrink-0">
          <div className="flex items-end justify-between gap-4 px-4 py-3">
            <div className="flex items-center gap-4">
              <div>
                <h1 className="text-[26px] font-bold tracking-tight leading-tight text-foreground">Chat</h1>
                <p className="text-sm text-muted-foreground mt-0.5">Direct gateway chat session for quick interventions.</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <input
                value={sessionKey}
                onChange={(e) => setSessionKey(e.target.value)}
                className="px-3 py-1.5 rounded-md border border-input bg-card text-sm font-mono focus:border-ring outline-none w-64"
                placeholder="session id"
              />
              <button onClick={() => setFocusMode(!focusMode)} className="p-2 rounded-md hover:bg-muted/30 text-muted-foreground hover:text-foreground transition-colors" title="Toggle focus mode">
                <Maximize2 className="h-4 w-4" />
              </button>
            </div>
          </div>
          {/* Tab bar */}
          <div className="flex gap-0 px-4">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={cn(
                  "inline-flex items-center gap-1.5 px-4 py-2 text-xs font-medium border-b-2 transition-colors -mb-px",
                  activeTab === tab.id
                    ? "border-primary text-foreground"
                    : "border-transparent text-muted-foreground hover:text-foreground hover:border-muted-foreground/30"
                )}
              >
                {tab.icon}
                {tab.label}
              </button>
            ))}
          </div>
        </div>
      )}

      {focusMode && (
        <button onClick={() => setFocusMode(false)} className="absolute top-2 right-2 z-10 p-2 rounded-full bg-card border border-border hover:bg-muted/30 text-muted-foreground">
          <X className="h-4 w-4" />
        </button>
      )}

      {/* Tab content */}
      {activeTab === "system-prompt" ? (
        <SystemPromptEditor />
      ) : activeTab === "live-log" ? (
        <LiveLogPanel />
      ) : (
        <div className={cn("flex flex-1 min-h-0", sidebarOpen && "gap-0")}>
          {/* Thread */}
          <div className={cn("flex flex-col flex-1 min-w-0", sidebarOpen && "flex-[0_0_60%]")}>
            <div ref={threadRef} className="flex-1 overflow-y-auto px-4 py-4 space-y-4" role="log">
              {loadingHistory && (
                <div className="text-xs text-muted-foreground text-center">Loading history…</div>
              )}
              {messages.map((msg) => (
                <MessageBubble
                  key={msg.id}
                  message={msg}
                  onInspect={openInSidebar}
                  onAction={(action, payload) => {
                    const actionMsg: LocalMessage = {
                      id: makeId("action"),
                      role: "user",
                      content: `[Action: ${action}] ${JSON.stringify(payload)}`,
                      timestamp: Date.now(),
                    };
                    setMessages((prev) => [...prev, actionMsg]);
                  }}
                />
              ))}
              {sending && (
                <div className="flex gap-3">
                  <div className="h-8 w-8 rounded-full bg-primary/20 flex items-center justify-center text-xs font-bold text-primary shrink-0">AI</div>
                  <div className="rounded-lg bg-card border border-border px-4 py-3 animate-[pulse-dot_1.5s_ease-in-out_infinite]">
                    <span className="text-sm text-muted-foreground">Thinking…</span>
                  </div>
                </div>
              )}
            </div>

            {/* Composer */}
            <div className="border-t border-border px-4 py-3 shrink-0 bg-background">
              {error && <Callout variant="danger" className="mb-3">{error}</Callout>}
              {!connected && !error && (
                <Callout variant="default" className="mb-3">
                  Event stream is idle — chat still works through the REST gateway.
                </Callout>
              )}
              <div className="flex gap-2">
                <div className="flex-1 relative">
                  <textarea
                    value={draft}
                    onChange={(e) => setDraft(e.target.value)}
                    onKeyDown={handleKeyDown}
                    disabled={sending}
                    placeholder="Message (↩ to send, Shift+↩ for line breaks)"
                    className="w-full px-3 py-2.5 rounded-lg border border-input bg-card text-sm resize-none min-h-[44px] max-h-40 focus:border-ring focus:ring-1 focus:ring-ring outline-none transition-colors font-sans"
                    rows={1}
                  />
                </div>
                <div className="flex flex-col gap-1.5 shrink-0">
                  <button onClick={handleNewSession} className="px-3 py-2 rounded-md border border-border bg-[hsl(var(--bg-elevated))] text-xs font-medium hover:bg-muted/30 transition-colors">
                    New session
                  </button>
                  <button onClick={() => void handleSend()} disabled={sending || !draft.trim()} className="px-3 py-2 rounded-md bg-primary text-primary-foreground text-xs font-medium hover:bg-primary/90 transition-colors disabled:opacity-50 flex items-center gap-1.5">
                    {sending ? "Sending" : "Send"}<kbd className="text-[10px] bg-primary-foreground/20 px-1 rounded">↵</kbd>
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* Sidebar — tool output inspector */}
          {sidebarOpen && (
            <div className="flex-[0_0_40%] border-l border-border bg-card flex flex-col min-w-0">
              <div className="flex items-center justify-between px-4 py-2 border-b border-border">
                <span className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Inspector</span>
                <button onClick={() => setSidebarOpen(false)} className="p-1 rounded hover:bg-muted/30 text-muted-foreground"><X className="h-3.5 w-3.5" /></button>
              </div>
              <div className="flex-1 overflow-auto p-3">
                {sidebarContent !== null ? (
                  <JsonRenderer data={sidebarContent} />
                ) : (
                  <div className="text-sm text-muted-foreground">Click a tool result to inspect.</div>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

