// ── GET /api/gemma/plugin-schema/:plugin ─────────────────────────────────────

/// Return a plugin's sealed-blob schema as JSON so the UI can render it via
/// json-render. The sealed blob catalog is the source of render truth.
pub async fn plugin_schema(
    State(_state): State<Arc<AppState>>,
    Path(plugin): Path<String>,
) -> impl IntoResponse {
    use op_blob::catalog::ActiveReflectionCatalog;
    let target = plugin.to_lowercase().replace('-', "_");
    match ActiveReflectionCatalog::open_shm() {
        Ok(catalog) => {
            let found = catalog
                .plugin_object_blobs()
                .into_iter()
                .find(|b| b.manifest.plugin_id == target);
            match found {
                Some(b) => {
                    let schema: serde_json::Value =
                        serde_json::from_str(&b.schema_json).unwrap_or(serde_json::Value::Null);
                    Json(serde_json::json!({
                        "plugin": b.manifest.plugin_id,
                        "schema_hash": b.manifest.schema_hash,
                        "schema": schema,
                    }))
                    .into_response()
                }
                None => (
                    StatusCode::NOT_FOUND,
                    format!("no sealed blob for plugin '{target}'"),
                )
                    .into_response(),
            }
        }
        Err(e) => (
            StatusCode::SERVICE_UNAVAILABLE,
            format!("blob catalog unavailable: {e}"),
        )
            .into_response(),
    }
}

