/**
 * Thin wrapper around json-render's `<Renderer>` bound to our component catalog
 * (`jsonRenderRegistry`). json-render only renders element `type`s that exist in
 * the catalog, so we also supply a visible fallback for any stray unknown type
 * rather than letting it silently vanish.
 */
import { Renderer } from "@json-render/react";
import type { Spec } from "@json-render/core";
import { jsonRenderRegistry } from "@/lib/json-render-catalog";

const CATALOG = new Set(Object.keys(jsonRenderRegistry));

function UnknownComponent({ element }: { element?: { type?: string } }) {
  return (
    <div className="text-[11px] font-mono text-danger border border-danger/30 rounded px-2 py-1">
      unknown component: {element?.type ?? "?"}
    </div>
  );
}

/** True iff every element `type` in the spec is registered in the catalog. */
export function specUsesOnlyCatalog(spec: Spec | null | undefined): boolean {
  if (!spec || typeof spec !== "object") return false;
  const elements =
    (spec as { elements?: Record<string, { type?: string }> }).elements ?? {};
  return Object.values(elements).every((el) => !!el && CATALOG.has(el.type ?? ""));
}

export function SpecRenderer({ spec }: { spec: Spec | null }) {
  return (
    <Renderer
      spec={spec}
      registry={jsonRenderRegistry}
      fallback={UnknownComponent as never}
    />
  );
}

/**
 * Renders a plugin's live sealed-blob schema via json-render. The schema is the
 * render source — fetched from `/api/gemma/plugin-schema/:plugin`, which reads
 * the sealed blob catalog. Used by both chat surfaces to surface the
 * `antigravity_chat` plugin schema.
 */
import { useEffect, useState } from "react";
import { SpecRenderer } from "@/components/gemma/SpecRenderer";
import { dataToSpec } from "@/lib/json-render-catalog";

interface Props {
  plugin?: string;
  title?: string;
  className?: string;
}

interface SchemaResponse {
  plugin: string;
  schema_hash?: string;
  schema: unknown;
}

export function PluginSchemaPanel({
  plugin = "antigravity_chat",
  title,
  className,
}: Props) {
  const [schema, setSchema] = useState<unknown>(null);
  const [hash, setHash] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let alive = true;
    setLoading(true);
    (async () => {
      try {
        const r = await fetch(`/api/gemma/plugin-schema/${plugin}`);
        if (!r.ok) throw new Error(`schema HTTP ${r.status}`);
        const j: SchemaResponse = await r.json();
        if (!alive) return;
        setSchema(j.schema ?? j);
        setHash(j.schema_hash ?? null);
        setError(null);
      } catch (e) {
        if (alive) setError((e as Error).message);
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => {
      alive = false;
    };
  }, [plugin]);

  return (
    <div className={className}>
      <div className="flex items-center justify-between mb-2">
        <span className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
          {title ?? `${plugin} schema`}
        </span>
        {hash && (
          <span className="text-[10px] font-mono text-muted-foreground">
            {hash.slice(0, 12)}
          </span>
        )}
      </div>
      {loading && <div className="text-xs text-muted-foreground">Loading schema…</div>}
      {error && (
        <div className="text-xs text-danger">Failed to load blob schema: {error}</div>
      )}
      {!loading && !error && schema != null && (
        <div className="rounded-md border border-border bg-background/40 p-2 max-h-[420px] overflow-auto">
          <SpecRenderer spec={dataToSpec(schema, plugin)} />
        </div>
      )}
    </div>
  );
}

import { useCallback, useEffect, useState } from "react";
import type { Spec } from "@json-render/core";
import { PageHeader, Card, Callout } from "@/components/shell/Primitives";
import { SpecRenderer } from "@/components/gemma/SpecRenderer";

interface SpecEntry {
  id: string;
  spec: Spec;
  prompt: string;
  tags: string[];
  created_at: number;
  signature: string;
}

interface Gallery {
  version: number;
  specs: SpecEntry[];
}

export default function GalleryPage() {
  const [specs, setSpecs] = useState<SpecEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const r = await fetch("/api/gemma/gallery");
      if (!r.ok) throw new Error(`gallery HTTP ${r.status}`);
      const g: Gallery = await r.json();
      setSpecs(g.specs ?? []);
      setError(null);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
    const t = setInterval(() => void load(), 5000);
    return () => clearInterval(t);
  }, [load]);

  const promote = async (id: string) => {
    setBusy(id);
    try {
      const r = await fetch(`/api/gemma/catalog/promote/${id}`, { method: "POST" });
      if (!r.ok) throw new Error(`promote HTTP ${r.status}`);
      setSpecs((prev) => prev.filter((s) => s.id !== id));
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(null);
    }
  };

  const remove = async (id: string) => {
    setBusy(id);
    try {
      const r = await fetch(`/api/gemma/gallery/${id}`, { method: "DELETE" });
      if (!r.ok && r.status !== 204) throw new Error(`delete HTTP ${r.status}`);
      setSpecs((prev) => prev.filter((s) => s.id !== id));
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(null);
    }
  };

  return (
    <div className="space-y-4">
      <PageHeader
        title="Gemma Gallery"
        subtitle="Live json-render specs generated by Gemma from the sealed blob catalog. Promote moves a spec into the finalized catalog."
      />
      {error && <Callout variant="danger">{error}</Callout>}
      {loading && specs.length === 0 && (
        <div className="text-sm text-muted-foreground">Loading gallery…</div>
      )}
      {!loading && specs.length === 0 && !error && (
        <Callout variant="default">
          Gallery is empty. Run the op-gemma binary with Ollama available to
          generate specs.
        </Callout>
      )}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {specs.map((entry) => (
          <Card
            key={entry.id}
            title={entry.id}
            actions={
              <div className="flex gap-1.5">
                <button
                  disabled={busy === entry.id}
                  onClick={() => void promote(entry.id)}
                  className="px-2 py-1 text-[11px] rounded-md bg-primary text-primary-foreground hover:bg-primary/90 disabled:opacity-50"
                >
                  Promote
                </button>
                <button
                  disabled={busy === entry.id}
                  onClick={() => void remove(entry.id)}
                  className="px-2 py-1 text-[11px] rounded-md border border-border hover:bg-muted/30 disabled:opacity-50"
                >
                  Delete
                </button>
              </div>
            }
          >
            <div className="rounded-md border border-border bg-background/40 p-2 max-h-[360px] overflow-auto">
              <SpecRenderer spec={entry.spec} />
            </div>
            {entry.prompt && (
              <p className="mt-2 text-[11px] text-muted-foreground line-clamp-3">
                {entry.prompt}
              </p>
            )}
          </Card>
        ))}
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from "react";
import type { Spec } from "@json-render/core";
import { PageHeader, Card, Callout } from "@/components/shell/Primitives";
import { SpecRenderer } from "@/components/gemma/SpecRenderer";

interface CatalogEntry {
  id: string;
  spec: Spec;
  prompt: string;
  tags: string[];
  created_at: number;
  signature: string;
  promoted_at: number;
  label?: string | null;
}

interface Catalog {
  version: number;
  entries: CatalogEntry[];
}

export default function CatalogPage() {
  const [entries, setEntries] = useState<CatalogEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const r = await fetch("/api/gemma/catalog");
      if (!r.ok) throw new Error(`catalog HTTP ${r.status}`);
      const c: Catalog = await r.json();
      setEntries(c.entries ?? []);
      setError(null);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const remove = async (id: string) => {
    setBusy(id);
    try {
      const r = await fetch(`/api/gemma/catalog/${id}`, { method: "DELETE" });
      if (!r.ok && r.status !== 204) throw new Error(`delete HTTP ${r.status}`);
      setEntries((prev) => prev.filter((e) => e.id !== id));
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setBusy(null);
    }
  };

  return (
    <div className="space-y-4">
      <PageHeader
        title="Gemma Catalog"
        subtitle="Finalized json-render specs promoted from the gallery."
      />
      {error && <Callout variant="danger">{error}</Callout>}
      {loading && entries.length === 0 && (
        <div className="text-sm text-muted-foreground">Loading catalog…</div>
      )}
      {!loading && entries.length === 0 && !error && (
        <Callout variant="default">
          No promoted specs yet. Promote specs from the Gallery.
        </Callout>
      )}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {entries.map((entry) => (
          <Card
            key={entry.id}
            title={entry.label || entry.id}
            actions={
              <button
                disabled={busy === entry.id}
                onClick={() => void remove(entry.id)}
                className="px-2 py-1 text-[11px] rounded-md border border-border hover:bg-muted/30 disabled:opacity-50"
              >
                Remove
              </button>
            }
          >
            <div className="rounded-md border border-border bg-background/40 p-2 max-h-[360px] overflow-auto">
              <SpecRenderer spec={entry.spec} />
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

