//! Embedded UI assets with static-dir override.
//!
//! In dev mode, if `OP_WEB_STATIC_DIR` is set, files are served from that
//! directory first — no binary rebuild needed to pick up UI changes.
//! Falls back to RustEmbed baked-in assets for release builds.

use axum::{
    body::Body,
    http::{header, StatusCode, Uri},
    response::{IntoResponse, Response},
};
use rust_embed::RustEmbed;

#[derive(RustEmbed, Clone)]
#[folder = "ui/dist/"]
pub struct Assets;

fn content_type(path: &str) -> &'static str {
    match path.rsplit('.').next() {
        Some("html") => "text/html; charset=utf-8",
        Some("js") => "application/javascript; charset=utf-8",
        Some("css") => "text/css; charset=utf-8",
        Some("json") => "application/json; charset=utf-8",
        Some("svg") => "image/svg+xml",
        Some("png") => "image/png",
        Some("jpg" | "jpeg") => "image/jpeg",
        Some("gif") => "image/gif",
        Some("ico") => "image/x-icon",
        Some("woff") => "font/woff",
        Some("woff2") => "font/woff2",
        Some("ttf") => "font/ttf",
        Some("eot") => "application/vnd.ms-fontobject",
        Some("map") => "application/json",
        Some("wasm") => "application/wasm",
        _ => "application/octet-stream",
    }
}

pub async fn serve_ui(uri: Uri) -> Response {
    let path = uri.path().trim_start_matches('/');

    // 1. Try OP_WEB_STATIC_DIR first (dev mode — no rebuild needed)
    if let Ok(static_dir) = std::env::var("OP_WEB_STATIC_DIR") {
        let static_root = std::path::PathBuf::from(&static_dir);
        let file_path = if path.is_empty() {
            static_root.join("index.html")
        } else {
            static_root.join(path)
        };

        if let Ok(bytes) = tokio::fs::read(&file_path).await {
            let ct = content_type(file_path.to_str().unwrap_or("index.html"));
            return (
                StatusCode::OK,
                [(header::CONTENT_TYPE, ct)],
                bytes,
            ).into_response();
        }

        // SPA fallback in static dir
        let index = static_root.join("index.html");
        if let Ok(bytes) = tokio::fs::read(&index).await {
            return (
                StatusCode::OK,
                [(header::CONTENT_TYPE, "text/html; charset=utf-8")],
                bytes,
            ).into_response();
        }
    }

    // 2. Fall back to embedded assets
    let asset_path = if path.is_empty() { "index.html" } else { path };
    if let Some(file) = Assets::get(asset_path) {
        return (
            StatusCode::OK,
            [(header::CONTENT_TYPE, content_type(asset_path))],
            file.data().to_vec(),  // hmm, this might not work with axum-embed's RustEmbed type
        ).into_response();
    }

    // 3. SPA fallback to embedded index.html
    if let Some(file) = Assets::get("index.html") {
        return (
            StatusCode::OK,
            [(header::CONTENT_TYPE, "text/html; charset=utf-8")],
            file.data().to_vec(),  // same issue
        ).into_response();
    }

    (StatusCode::NOT_FOUND, "Not Found").into_response()
}
