const AUTHORING_INSTRUCTIONS: &str = r#"
## Your Role
You are an expert in the json-render.dev Spec format and the opdbus control plane.
When asked to create UI elements, ALWAYS emit a valid json-render Spec inside a
fenced code block tagged `json-render`. The block MUST be parseable JSON with a
`root` key (string) and an `elements` key (object).

## Required output format for UI elements
```json-render
{"root":"<root-key>","elements":{"<key>":{"type":"<component>","props":{...},"children":["<child-key>"]}}}
```

Use only these component types: container, card, kv, heading, text, badge, row, code.
Reference the json-render authoring guide and active blob state above to render real data.
Never use placeholder values when real plugin field data is available in the blob context.
"#;

// ── Helpers ──────────────────────────────────────────────────────────────────

/// Ollama model tag for Gemma inference. Override with `GEMMA_MODEL`.
/// Default: `gemma4:e4b` (one size up from the smallest `e2b`).
pub fn gemma_model() -> String {
    std::env::var("GEMMA_MODEL").unwrap_or_else(|_| "gemma4:e4b".to_string())
}

/// The json-render component catalog. Must match the frontend `jsonRenderRegistry`;
/// json-render will not render a `type` absent from its catalog.
const ALLOWED_COMPONENTS: &[&str] = &[
    "container",
    "card",
    "kv",
    "heading",
    "text",
    "badge",
    "row",
    "code",
];

/// True iff the spec is structurally sound and every element `type` is in the
/// json-render catalog and every child reference resolves.
fn spec_is_catalog_valid(v: &serde_json::Value) -> bool {
    let Some(root) = v.get("root").and_then(|r| r.as_str()) else {
        return false;
    };
    let Some(elements) = v.get("elements").and_then(|e| e.as_object()) else {
        return false;
    };
    if elements.is_empty() || !elements.contains_key(root) {
        return false;
    }
    for el in elements.values() {
        let Some(ty) = el.get("type").and_then(|t| t.as_str()) else {
            return false;
        };
        if !ALLOWED_COMPONENTS.contains(&ty) {
            return false;
        }
        if let Some(children) = el.get("children").and_then(|c| c.as_array()) {
            for child in children {
                match child.as_str() {
                    Some(key) if elements.contains_key(key) => {}
                    _ => return false,
                }
            }
        }
    }
    true
}

/// Wrap an mpsc receiver into an SSE body. All chat return paths funnel through
/// this one function so they share a single concrete stream type (required by the
/// `impl IntoResponse` return of `chat_stream`).
fn sse_stream(
    rx: mpsc::Receiver<Result<Event, Infallible>>,
) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
    Sse::new(stream::unfold(rx, |mut rx| async move {
        rx.recv().await.map(|e| (e, rx))
    }))
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn spec_signature(elements: &serde_json::Value) -> String {
    let bytes = serde_json::to_vec(elements).unwrap_or_default();
    let hash = blake3::hash(&bytes);
    hex::encode(&hash.as_bytes()[..8])
}

/// Extract all ```json-render ... ``` blocks from a response string.
fn extract_specs(text: &str, prompt: &str) -> Vec<GemmaSpecEntry> {
    let mut out = Vec::new();
    let mut remaining = text;
    while let Some(start) = remaining.find("```json-render") {
        let after_fence = &remaining[start + 14..];
        // skip optional whitespace / newline after the fence tag
        let content_start = after_fence.find('\n').map(|i| i + 1).unwrap_or(0);
        let content = &after_fence[content_start..];
        if let Some(end) = content.find("\n```") {
            let block = &content[..end];
            match serde_json::from_str::<serde_json::Value>(block.trim()) {
                Ok(v) if spec_is_catalog_valid(&v) => {
                    let elements = v
                        .get("elements")
                        .cloned()
                        .unwrap_or(serde_json::Value::Null);
                    let entry = GemmaSpecEntry {
                        id: format!("spec-{}", uuid::Uuid::new_v4()),
                        spec: v,
                        prompt: prompt.to_string(),
                        tags: vec![],
                        created_at: now_secs(),
                        signature: spec_signature(&elements),
                    };
                    out.push(entry);
                    remaining = &content[end + 4..];
                }
                Ok(_) => {
                    warn!("gemma: json-render block invalid or uses non-catalog components");
                    remaining = &content[end + 4..];
                }
                Err(e) => {
                    warn!("gemma: json-render block parse failed: {e}");
                    remaining = &content[end + 4..];
                }
            }
        } else {
            break;
        }
    }
    out
}

// ── POST /api/gemma/chat ─────────────────────────────────────────────────────

pub async fn chat_stream(
    State(state): State<Arc<AppState>>,
    Json(req): Json<GemmaChatRequest>,
) -> impl IntoResponse {
    let base_url =
        std::env::var("OLLAMA_BASE_URL").unwrap_or_else(|_| "http://127.0.0.1:11434".to_string());
    let model = gemma_model();

    // Sweep expired sessions (30 min TTL).
    let ttl = Duration::from_secs(1800);
    state
        .gemma_sessions
        .retain(|_, v| v.last_active.elapsed() < ttl);

    // Load or create session.
    let history: Vec<GemmaChatMessage> = state
        .gemma_sessions
        .get(&req.session_id)
        .map(|s| s.messages.clone())
        .unwrap_or_default();

    // Build system prompt.
    let shm_ctx = op_gemma::build_shm_context();
    let system_prompt = format!(
        "{}\n\n---\n\n{}\n\n---\n\n{}",
        op_gemma::JSON_RENDER_REFERENCE,
        shm_ctx,
        AUTHORING_INSTRUCTIONS,
    );

    // Build message list.
    let mut messages: Vec<GemmaChatMessage> = vec![GemmaChatMessage {
        role: "system".into(),
        content: system_prompt,
    }];
    // Keep at most last 49 history messages (system is index 0).
    let tail = if history.len() > 49 {
        &history[history.len() - 49..]
    } else {
        &history
    };
    messages.extend_from_slice(tail);
    messages.push(GemmaChatMessage {
        role: "user".into(),
        content: req.message.clone(),
    });

    let ollama_body = OllamaRequest {
        model: model.clone(),
        stream: true,
        messages,
    };

    // Open Ollama connection.
    let resp = match state
        .reqwest_client
        .post(format!("{base_url}/api/chat"))
        .json(&ollama_body)
        .send()
        .await
    {
        Err(e) => {
            let msg = format!("Ollama unreachable at {base_url} — is ollama running? ({e})");
            warn!("{msg}");
            let (tx, rx) = mpsc::channel::<Result<Event, Infallible>>(4);
            let _ = tx
                .send(Ok(
                    Event::default().data(serde_json::json!({"error": msg}).to_string())
                ))
                .await;
            return sse_stream(rx).keep_alive(KeepAlive::default());
        }
        Ok(r) if r.status() == 404 => {
            let msg = format!("Model {model} not available. Run: ollama pull {model}");
            warn!("{msg}");
            let (tx, rx) = mpsc::channel::<Result<Event, Infallible>>(4);
            let _ = tx
                .send(Ok(
                    Event::default().data(serde_json::json!({"error": msg}).to_string())
                ))
                .await;
            return sse_stream(rx).keep_alive(KeepAlive::default());
        }
        Ok(r) if !r.status().is_success() => {
            let status = r.status();
            let msg = format!("Ollama returned HTTP {status}");
            warn!("{msg}");
            let (tx, rx) = mpsc::channel::<Result<Event, Infallible>>(4);
            let _ = tx
                .send(Ok(
                    Event::default().data(serde_json::json!({"error": msg}).to_string())
                ))
                .await;
            return sse_stream(rx).keep_alive(KeepAlive::default());
        }
        Ok(r) => r,
    };

    info!(
        "gemma: streaming from Ollama for session {}",
        req.session_id
    );

    let (tx, rx) = mpsc::channel::<Result<Event, Infallible>>(64);
    let session_id = req.session_id.clone();
    let user_message = req.message.clone();
    let sessions = Arc::clone(&state.gemma_sessions);

    tokio::spawn(async move {
        let mut byte_stream = resp.bytes_stream();
        let mut full = String::new();
        let mut line_buf = String::new();

        while let Some(chunk) = byte_stream.next().await {
            let bytes = match chunk {
                Ok(b) => b,
                Err(e) => {
                    warn!("gemma stream read error: {e}");
                    break;
                }
            };
            line_buf.push_str(&String::from_utf8_lossy(&bytes));

            // Process all complete lines.
            while let Some(nl) = line_buf.find('\n') {
                let line = line_buf[..nl].trim().to_string();
                line_buf = line_buf[nl + 1..].to_string();

                if line.is_empty() {
                    continue;
                }
                match serde_json::from_str::<OllamaChunk>(&line) {
                    Ok(chunk) => {
                        if !chunk.message.content.is_empty() {
                            full.push_str(&chunk.message.content);
                            let evt = serde_json::json!({"delta": chunk.message.content});
                            let _ = tx.send(Ok(Event::default().data(evt.to_string()))).await;
                        }
                        if chunk.done {
                            let specs = extract_specs(&full, &user_message);
                            let done_evt = serde_json::json!({
                                "done": true,
                                "full": full,
                                "specs": specs,
                            });
                            let _ = tx
                                .send(Ok(Event::default().data(done_evt.to_string())))
                                .await;

                            // Persist to session.
                            let mut entry =
                                sessions.entry(session_id.clone()).or_insert_with(|| {
                                    GemmaSession {
                                        messages: vec![],
                                        last_active: std::time::Instant::now(),
                                    }
                                });
                            entry.messages.push(GemmaChatMessage {
                                role: "user".into(),
                                content: user_message.clone(),
                            });
                            entry.messages.push(GemmaChatMessage {
                                role: "assistant".into(),
                                content: full.clone(),
                            });
                            entry.last_active = std::time::Instant::now();
                        }
                    }
                    Err(e) => {
                        warn!("gemma: chunk parse failed: {e} — line: {line}");
                    }
                }
            }
        }
    });

    sse_stream(rx).keep_alive(KeepAlive::new().interval(Duration::from_secs(15)))
}

