// ── PATCH /api/gemma/catalog/:id ─────────────────────────────────────────────

pub async fn catalog_update(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
    Json(req): Json<CatalogUpdateRequest>,
) -> impl IntoResponse {
    let _lock = state.gemma_catalog_lock.lock().await;
    let mut catalog = match store::read_catalog() {
        Ok(c) => c,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };

    let entry = catalog.entries.iter_mut().find(|e| e.base.id == id);
    let Some(entry) = entry else {
        return StatusCode::NOT_FOUND.into_response();
    };

    if let Some(label) = req.label {
        entry.label = Some(label);
    }
    if let Some(tags) = req.tags {
        entry.base.tags = tags;
    }

    match store::write_catalog(&catalog) {
        Ok(()) => StatusCode::OK.into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

// ── GET /api/gemma/plugin-schema/:plugin ─────────────────────────────────────

/// Return a plugin's sealed-blob schema as JSON so the UI can render it via
/// json-render. The sealed blob catalog is the source of render truth.
pub async fn plugin_schema(
    State(_state): State<Arc<AppState>>,
    Path(plugin): Path<String>,
) -> impl IntoResponse {
    use op_blob::catalog::ActiveReflectionCatalog;
    let target = plugin.to_lowercase().replace('-', "_");
    match ActiveReflectionCatalog::open_shm() {
        Ok(catalog) => {
            let found = catalog
                .plugin_object_blobs()
                .into_iter()
                .find(|b| b.manifest.plugin_id == target);
            match found {
                Some(b) => {
                    let schema: serde_json::Value =
                        serde_json::from_str(&b.schema_json).unwrap_or(serde_json::Value::Null);
                    Json(serde_json::json!({
                        "plugin": b.manifest.plugin_id,
                        "schema_hash": b.manifest.schema_hash,
                        "schema": schema,
                    }))
                    .into_response()
                }
                None => (
                    StatusCode::NOT_FOUND,
                    format!("no sealed blob for plugin '{target}'"),
                )
                    .into_response(),
            }
        }
        Err(e) => (
            StatusCode::SERVICE_UNAVAILABLE,
            format!("blob catalog unavailable: {e}"),
        )
            .into_response(),
    }
}

