// ── GET /api/gemma/proto/:plugin ───────────────────────────────────────────────

/// Export a plugin's sealed-blob FileDescriptorSet as `.proto` text.
/// Lovable (and other tooling) uses this for TypeScript protobuf-ts generation.
/// The descriptor bytes come from SHM blob catalog; no compile-time protos needed.
pub async fn plugin_proto(
    State(_state): State<Arc<AppState>>,
    Path(plugin): Path<String>,
) -> impl IntoResponse {
    use prost::Message;
    use prost_reflect::{DescriptorPool, prost_types::FileDescriptorSet};

    let target = plugin.to_lowercase().replace('-', "_");
    let catalog_result = op_blob::catalog::ActiveReflectionCatalog::open_shm();

    match catalog_result {
        Ok(catalog) => {
            let found = catalog
                .plugin_object_blobs()
                .into_iter()
                .find(|b| b.manifest.plugin_id == target);

            match found {
                Some(blob) => {
                    // Decode the sealed blob's FileDescriptorSet
                    let descriptor_bytes = blob.descriptor_set();
                    let file_set: FileDescriptorSet =
                        match FileDescriptorSet::decode(descriptor_bytes.as_slice()) {
                            Ok(fs) => fs,
                            Err(_) => {
                                return (
                                    StatusCode::INTERNAL_SERVER_ERROR,
                                    "failed to decode descriptor set",
                                )
                                    .into_response();
                            }
                        };

                    // Convert to text proto using prost-reflect
                    let pool = DescriptorPool::decode(descriptor_bytes.as_slice());
                    let mut text_output = String::new();

                    if let Ok(pool) = pool {
                        for file in &file_set.file {
                            if let Some(name) = &file.name {
                                // Add package and syntax header
                                text_output.push_str("syntax = \"proto3\";\n\n");
                                if let Some(pkg) = &file.package {
                                    text_output.push_str(&format!("package {pkg};\n\n"));
                                }

                                // Add imports
                                for dep in &file.dependency {
                                    text_output.push_str(&format!("import \"{dep}\";\n"));
                                }
                                if !file.dependency.is_empty() {
                                    text_output.push('\n');
                                }

                                // Messages and services would be formatted here
                                // For now, output the raw file name to signal availability
                                text_output.push_str(&format!("// Generated from: {name}\n"));
                            }
                        }
                    } else {
                        // Fallback: just indicate the descriptor is available
                        text_output.push_str(&format!(
                            "// Plugin {} descriptor available ({} bytes)\n",
                            target,
                            descriptor_bytes.len()
                        ));
                    }

                    let mut headers = HeaderMap::new();
                    headers.insert(
                        axum::http::header::CONTENT_TYPE,
                        HeaderValue::from_static("text/plain; charset=utf-8"),
                    );
                    (headers, text_output).into_response()
                }
                None => (
                    StatusCode::NOT_FOUND,
                    format!("no sealed blob for plugin '{target}'"),
                )
                    .into_response(),
            }
        }
        Err(e) => (
            StatusCode::SERVICE_UNAVAILABLE,
            format!("blob catalog unavailable: {e}"),
        )
            .into_response(),
    }
}

