// ── GET /api/gemma/plugin-proto/:plugin ───────────────────────────────────────

/// Generate a plugin's gRPC proto as TEXT for TypeScript/protobuf-ts codegen.
/// Reads the sealed blob from SHM, reconstructs proto definitions from the schema.
/// Covers dynamically-registered plugins that have no static .proto files.
pub async fn plugin_proto(
    State(_state): State<Arc<AppState>>,
    Path(plugin): Path<String>,
) -> impl IntoResponse {
    use op_grpc_bridge::plugin_grpc_gen::generate_plugin_method_protos;
    use op_state_store::PluginSchema;

    let target = plugin.to_lowercase().replace('-', "_");

    // Read schema from SHM blob
    let schema: PluginSchema = match op_blob::catalog::read_plugin_schema_shm(&target) {
        Some(s) => s,
        None => {
            return (
                StatusCode::NOT_FOUND,
                format!("no sealed blob for plugin '{target}'"),
            )
                .into_response();
        }
    };

    // Generate text proto from schema
    let proto = generate_plugin_method_protos(&[target.clone()], &schema);

    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("text/plain; charset=utf-8"),
    );
    (headers, proto).into_response()
}

// ── GET /api/gemma/all-plugin-protos ───────────────────────────────────────────

/// Generate text protos for ALL active plugins in the SHM catalog.
/// Produces a unified proto file covering all dynamically-registered methods.
/// For Lovable: fetch this endpoint and use with protoc-ts.
pub async fn all_plugin_protos(
    State(_state): State<Arc<AppState>>,
) -> impl IntoResponse {
    use op_grpc_bridge::plugin_grpc_gen::generate_plugin_method_protos;
    use op_state_store::PluginSchema;

    let plugin_ids = match op_blob::catalog::read_manifest_plugin_ids_shm() {
        Some(ids) => ids,
        None => {
            return (
                StatusCode::SERVICE_UNAVAILABLE,
                "blob catalog unavailable",
            )
                .into_response();
        }
    };

    let mut plugin_schemas: Vec<(String, PluginSchema)> = Vec::new();
    for plugin_id in plugin_ids {
        if let Some(schema) = op_blob::catalog::read_plugin_schema_shm(&plugin_id) {
            plugin_schemas.push((plugin_id, schema));
        }
    }

    // Generate unified proto for all plugins
    let proto = generate_plugin_method_protos(&plugin_schemas.iter().map(|(id, s)| (id.clone(), s.clone())).collect::<Vec<_>>());

    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("text/plain; charset=utf-8"),
    );
    (headers, proto).into_response()
}

