/// Export a plugin's sealed-blob FileDescriptorSet as binary.
/// For tooling that needs the full descriptor (e.g., protoc --descriptor_set_in).
/// The gRPC bridge already serves this via reflection, but this provides HTTP access.
pub async fn plugin_proto_bytes(
    State(_state): State<Arc<AppState>>,
    Path(plugin): Path<String>,
) -> impl IntoResponse {
    let target = plugin.to_lowercase().replace('-', "_");
    let catalog_result = op_blob::catalog::ActiveReflectionCatalog::open_shm();

    match catalog_result {
        Ok(catalog) => {
            let found = catalog
                .plugin_object_blobs()
                .into_iter()
                .find(|b| b.manifest.plugin_id == target);

            match found {
                Some(blob) => {
                    let descriptor_bytes = blob.descriptor_set();
                    let mut headers = HeaderMap::new();
                    headers.insert(
                        axum::http::header::CONTENT_TYPE,
                        HeaderValue::from_static("application/octet-stream"),
                    );
                    (headers, descriptor_bytes).into_response()
                }
                None => (
                    StatusCode::NOT_FOUND,
                    format!("no sealed blob for plugin '{target}'"),
                )
                    .into_response(),
            }
        }
        Err(e) => (
            StatusCode::SERVICE_UNAVAILABLE,
            format!("blob catalog unavailable: {e}"),
        )
            .into_response(),
    }
}

