syntax = "proto3";

package operation.v1;

import "google/protobuf/any.proto";
import "google/protobuf/timestamp.proto";
import "google/protobuf/struct.proto";
import "google/protobuf/empty.proto";

// =============================================================================
// Core State Synchronization Service
// =============================================================================

// Bidirectional state sync between D-Bus and gRPC clients
service StateSync {
  // Subscribe to all state changes (D-Bus -> gRPC streaming)
  rpc Subscribe(SubscribeRequest) returns (stream StateChange);

  // Apply a mutation (gRPC -> D-Bus -> Event Chain)
  rpc Mutate(MutateRequest) returns (MutateResponse);

  // Get current state snapshot
  rpc GetState(GetStateRequest) returns (GetStateResponse);

  // Batch mutations (transactional)
  rpc BatchMutate(BatchMutateRequest) returns (BatchMutateResponse);
}

// =============================================================================
// Plugin Service - Per-plugin operations
// =============================================================================

service PluginService {
  // List all registered plugins
  rpc ListPlugins(google.protobuf.Empty) returns (ListPluginsResponse);

  // Get plugin schema (JSON Schema 2026)
  rpc GetSchema(GetSchemaRequest) returns (GetSchemaResponse);

  // Call a plugin method
  rpc CallMethod(CallMethodRequest) returns (CallMethodResponse);

  // Get/Set property
  rpc GetProperty(GetPropertyRequest) returns (GetPropertyResponse);
  rpc SetProperty(SetPropertyRequest) returns (SetPropertyResponse);

  // Subscribe to plugin signals
  rpc SubscribeSignals(SubscribeSignalsRequest) returns (stream Signal);
}

// =============================================================================
// Event Chain Service - Audit and compliance
// =============================================================================

service EventChainService {
  // Get events in range
  rpc GetEvents(GetEventsRequest) returns (GetEventsResponse);

  // Subscribe to new events as they occur
  rpc SubscribeEvents(SubscribeEventsRequest) returns (stream ChainEvent);

  // Verify chain integrity
  rpc VerifyChain(VerifyChainRequest) returns (VerifyChainResponse);

  // Get Merkle proof for an event
  rpc GetProof(GetProofRequest) returns (GetProofResponse);

  // Prove tag immutability
  rpc ProveTagImmutability(ProveTagImmutabilityRequest) returns (ProveTagImmutabilityResponse);

  // Get/Create snapshot
  rpc GetSnapshot(GetSnapshotRequest) returns (GetSnapshotResponse);
  rpc CreateSnapshot(CreateSnapshotRequest) returns (CreateSnapshotResponse);

  // Trace-scoped semantic lookup for the Accountability pane
  rpc SearchSemanticTrace(SearchSemanticTraceRequest) returns (SearchSemanticTraceResponse);
}

// =============================================================================
// Message Types - State Sync
// =============================================================================

message SubscribeRequest {
  // Filter by plugin IDs (empty = all)
  repeated string plugin_ids = 1;
  // Filter by object paths (glob patterns supported)
  repeated string path_patterns = 2;
  // Filter by tags
  repeated string tags = 3;
  // Include initial state snapshot
  bool include_initial_state = 4;
}

message StateChange {
  // Unique change ID
  string change_id = 1;
  // Event chain event ID
  uint64 event_id = 2;
  // Plugin that changed
  string plugin_id = 3;
  // D-Bus object path
  string object_path = 4;
  // Change type
  ChangeType change_type = 5;
  // Property/method name (if applicable)
  string member_name = 6;
  // Previous value (for updates)
  google.protobuf.Value old_value = 7;
  // New value
  google.protobuf.Value new_value = 8;
  // Tags touched by this change
  repeated string tags_touched = 9;
  // Event hash for verification
  string event_hash = 10;
  // Timestamp
  google.protobuf.Timestamp timestamp = 11;
  // Actor who made the change
  string actor_id = 12;
}

enum ChangeType {
  CHANGE_TYPE_UNSPECIFIED = 0;
  CHANGE_TYPE_PROPERTY_SET = 1;
  CHANGE_TYPE_PROPERTY_DELETE = 2;
  CHANGE_TYPE_METHOD_CALL = 3;
  CHANGE_TYPE_SIGNAL = 4;
  CHANGE_TYPE_OBJECT_ADDED = 5;
  CHANGE_TYPE_OBJECT_REMOVED = 6;
  CHANGE_TYPE_SCHEMA_MIGRATION = 7;
}

message MutateRequest {
  // Plugin to mutate
  string plugin_id = 1;
  // D-Bus object path
  string object_path = 2;
  // Operation type
  OperationType operation = 3;
  // Member (property or method name)
  string member_name = 4;
  // Arguments/value
  google.protobuf.Value value = 5;
  // Actor ID for audit
  string actor_id = 6;
  // Capability ID for authorization
  string capability_id = 7;
  // Idempotency key
  string idempotency_key = 8;
}

enum OperationType {
  OPERATION_TYPE_UNSPECIFIED = 0;
  OPERATION_TYPE_SET_PROPERTY = 1;
  OPERATION_TYPE_CALL_METHOD = 2;
  OPERATION_TYPE_APPLY_PATCH = 3;
}

message MutateResponse {
  // Whether mutation succeeded
  bool success = 1;
  // Event chain event ID
  uint64 event_id = 2;
  // Event hash
  string event_hash = 3;
  // Result value (for method calls)
  google.protobuf.Value result = 4;
  // Error details if failed
  MutationError error = 5;
  // Resulting effective state hash
  string effective_hash = 6;
}

message MutationError {
  ErrorCode code = 1;
  string message = 2;
  // Denial reason from event chain
  DenyReason deny_reason = 3;
}

enum ErrorCode {
  ERROR_CODE_UNSPECIFIED = 0;
  ERROR_CODE_NOT_FOUND = 1;
  ERROR_CODE_PERMISSION_DENIED = 2;
  ERROR_CODE_VALIDATION_FAILED = 3;
  ERROR_CODE_READ_ONLY = 4;
  ERROR_CODE_TAG_LOCKED = 5;
  ERROR_CODE_INTERNAL = 6;
}

message DenyReason {
  oneof reason {
    TagLock tag_lock = 1;
    ConstraintFail constraint_fail = 2;
    CapabilityMissing capability_missing = 3;
    ReadOnlyViolation read_only_violation = 4;
  }
}

message TagLock {
  string tag = 1;
  string wrapper_id = 2;
}

message ConstraintFail {
  string constraint = 1;
  string message = 2;
}

message CapabilityMissing {
  string capability = 1;
}

message ReadOnlyViolation {
  string field = 1;
}

message GetStateRequest {
  string plugin_id = 1;
  string object_path = 2;
}

message GetStateResponse {
  google.protobuf.Struct state = 1;
  string effective_hash = 2;
  uint64 at_event_id = 3;
}

message BatchMutateRequest {
  repeated MutateRequest mutations = 1;
  // All-or-nothing semantics
  bool atomic = 2;
  string actor_id = 3;
}

message BatchMutateResponse {
  bool success = 1;
  repeated MutateResponse results = 2;
  // If atomic and failed, which index failed
  int32 failed_index = 3;
}

// =============================================================================
// Message Types - Plugin Service
// =============================================================================

message ListPluginsResponse {
  repeated PluginInfo plugins = 1;
}

message PluginInfo {
  string id = 1;
  string name = 2;
  string version = 3;
  string description = 4;
  string dbus_path = 5;
  repeated string interfaces = 6;
  repeated string tags = 7;
}

message GetSchemaRequest {
  string plugin_id = 1;
  // Schema format (json-schema-2026, json-schema-draft07, protobuf)
  string format = 2;
}

message GetSchemaResponse {
  string schema_json = 1;
  string dialect = 2;
  string version = 3;
}

message CallMethodRequest {
  string plugin_id = 1;
  string object_path = 2;
  string interface_name = 3;
  string method_name = 4;
  repeated google.protobuf.Value arguments = 5;
  string actor_id = 6;
  string capability_id = 7;
}

message CallMethodResponse {
  bool success = 1;
  google.protobuf.Value result = 2;
  uint64 event_id = 3;
  string event_hash = 4;
  MutationError error = 5;
}

message GetPropertyRequest {
  string plugin_id = 1;
  string object_path = 2;
  string interface_name = 3;
  string property_name = 4;
}

message GetPropertyResponse {
  google.protobuf.Value value = 1;
  bool read_only = 2;
}

message SetPropertyRequest {
  string plugin_id = 1;
  string object_path = 2;
  string interface_name = 3;
  string property_name = 4;
  google.protobuf.Value value = 5;
  string actor_id = 6;
  string capability_id = 7;
}

message SetPropertyResponse {
  bool success = 1;
  uint64 event_id = 2;
  string event_hash = 3;
  MutationError error = 4;
}

message SubscribeSignalsRequest {
  string plugin_id = 1;
  repeated string signal_names = 2;
  string object_path = 3;
}

message Signal {
  string plugin_id = 1;
  string object_path = 2;
  string interface_name = 3;
  string signal_name = 4;
  repeated google.protobuf.Value arguments = 5;
  google.protobuf.Timestamp timestamp = 6;
}

// =============================================================================
// Message Types - Event Chain Service
// =============================================================================

message GetEventsRequest {
  uint64 from_event_id = 1;
  uint64 to_event_id = 2;
  // Max events to return
  uint32 limit = 3;
  // Filter by plugin
  string plugin_id = 4;
  // Filter by tags
  repeated string tags = 5;
  // Filter by decision
  Decision decision_filter = 6;
}

enum Decision {
  DECISION_UNSPECIFIED = 0;
  DECISION_ALLOW = 1;
  DECISION_DENY = 2;
}

message GetEventsResponse {
  repeated ChainEvent events = 1;
  bool has_more = 2;
}

message ChainEvent {
  uint64 event_id = 1;
  string prev_hash = 2;
  string event_hash = 3;
  google.protobuf.Timestamp timestamp = 4;
  string actor_id = 5;
  string capability_id = 6;
  string plugin_id = 7;
  string schema_version = 8;
  string operation_type = 9;
  string target = 10;
  repeated string tags_touched = 11;
  Decision decision = 12;
  DenyReason deny_reason = 13;
  string input_patch_hash = 14;
  string result_effective_hash = 15;
}

message SubscribeEventsRequest {
  // Start from this event ID (0 = latest)
  uint64 from_event_id = 1;
  // Filter by plugin
  string plugin_id = 2;
  // Filter by tags
  repeated string tags = 3;
}

message VerifyChainRequest {
  // Verify from this event
  uint64 from_event_id = 1;
  // Verify to this event (0 = latest)
  uint64 to_event_id = 2;
}

message VerifyChainResponse {
  bool valid = 1;
  uint64 events_verified = 2;
  uint64 batches_verified = 3;
  repeated string errors = 4;
}

message GetProofRequest {
  uint64 event_id = 1;
}

message GetProofResponse {
  string event_hash = 1;
  repeated MerkleProofSibling siblings = 2;
  string root = 3;
  uint64 batch_first_event_id = 4;
  uint64 batch_last_event_id = 5;
}

message MerkleProofSibling {
  string hash = 1;
  bool is_right = 2;
}

message ProveTagImmutabilityRequest {
  string tag = 1;
  // Optional: prove for specific plugin only
  string plugin_id = 2;
}

message ProveTagImmutabilityResponse {
  string tag = 1;
  bool is_immutable = 2;
  repeated uint64 violation_event_ids = 3;
  uint64 total_events_checked = 4;
}

message GetSnapshotRequest {
  string snapshot_id = 1;
}

message GetSnapshotResponse {
  Snapshot snapshot = 1;
}

message CreateSnapshotRequest {
  string plugin_id = 1;
}

message CreateSnapshotResponse {
  Snapshot snapshot = 1;
}

message Snapshot {
  string snapshot_id = 1;
  uint64 at_event_id = 2;
  string plugin_id = 3;
  string schema_version = 4;
  string stub_hash = 5;
  string immutable_wrappers_hash = 6;
  string tunable_patch_hash = 7;
  string effective_hash = 8;
  google.protobuf.Timestamp timestamp = 9;
  google.protobuf.Struct state = 10;
}

message SearchSemanticTraceRequest {
  // Max matches to return (0 = server default)
  uint32 limit = 1;
}

message SearchSemanticTraceResponse {
  string trace_id = 1;
  uint64 mutation_index = 2;
  repeated SemanticTraceMatch matches = 3;
}

message SemanticTraceMatch {
  string point_id = 1;
  float score = 2;
  google.protobuf.Struct payload = 3;
}

// =============================================================================
// OVSDB Mirror Service - RFC 7047 native gRPC bridge
// =============================================================================

// 1:1 gRPC projection of the OVSDB management protocol (RFC 7047).
// All operations pass through to ovsdb-server via the D-Bus mirror.
service OvsdbMirror {
  // RFC 7047 §4.1.1 — List available databases
  rpc ListDbs(google.protobuf.Empty) returns (OvsdbListDbsResponse);

  // RFC 7047 §4.1.2 — Get database schema (<database-schema>)
  rpc GetSchema(OvsdbGetSchemaRequest) returns (OvsdbGetSchemaResponse);

  // RFC 7047 §4.1.3 — Execute a transaction (insert/select/update/mutate/delete/wait)
  rpc Transact(OvsdbTransactRequest) returns (OvsdbTransactResponse);

  // RFC 7047 §4.1.5 — Monitor database changes (streaming)
  rpc Monitor(OvsdbMonitorRequest) returns (stream OvsdbUpdate);

  // RFC 7047 §4.1.11 — Echo for liveness
  rpc Echo(OvsdbEchoRequest) returns (OvsdbEchoResponse);

  // Dump full database state (convenience, not in RFC)
  rpc DumpDb(OvsdbDumpDbRequest) returns (OvsdbDumpDbResponse);

  // Get the full Bridge→Port→Interface hierarchy (reconciled mirror view)
  rpc GetBridgeState(OvsdbGetBridgeStateRequest) returns (OvsdbGetBridgeStateResponse);
}

// --- OVSDB Mirror Messages ---

message OvsdbListDbsResponse {
  repeated string databases = 1;
}

message OvsdbGetSchemaRequest {
  string database = 1;
}

message OvsdbGetSchemaResponse {
  // RFC 7047 §3.2 <database-schema> as JSON
  string schema_json = 1;
  string name = 2;
  string version = 3;
}

message OvsdbTransactRequest {
  string database = 1;
  // RFC 7047 §4.1.3 — array of operations as JSON
  string operations_json = 2;
  // Actor for event chain audit
  string actor_id = 3;
}

message OvsdbTransactResponse {
  bool success = 1;
  // Array of per-operation results as JSON
  string results_json = 2;
  // Event chain event ID (if recorded)
  uint64 event_id = 3;
  string error = 4;
}

message OvsdbMonitorRequest {
  string database = 1;
  // RFC 7047 §4.1.5 — monitor-requests per table as JSON
  // e.g. {"Bridge": {}, "Port": {}, "Interface": {}}
  string monitor_requests_json = 2;
}

message OvsdbUpdate {
  // Table name
  string table = 1;
  // Row UUID
  string uuid = 2;
  // Old row (null for inserts)
  google.protobuf.Struct old_row = 3;
  // New row (null for deletes)
  google.protobuf.Struct new_row = 4;
  google.protobuf.Timestamp timestamp = 5;
}

message OvsdbEchoRequest {
  repeated string payload = 1;
}

message OvsdbEchoResponse {
  repeated string payload = 1;
}

message OvsdbDumpDbRequest {
  string database = 1;
}

message OvsdbDumpDbResponse {
  // Full database dump as JSON (table → rows)
  string dump_json = 1;
}

message OvsdbGetBridgeStateRequest {
  // Optional: filter by bridge name (empty = all)
  string bridge_name = 1;
}

message OvsdbGetBridgeStateResponse {
  repeated OvsdbBridge bridges = 1;
}

// RFC 7047 Bridge table — hierarchical view
message OvsdbBridge {
  string name = 1;
  string datapath_type = 2;
  string fail_mode = 3;
  bool stp_enable = 4;
  bool mcast_snooping_enable = 5;
  map<string, string> other_config = 6;
  repeated OvsdbPort ports = 7;
}

// RFC 7047 Port table
message OvsdbPort {
  string name = 1;
  uint32 tag = 2;       // VLAN tag (0 = untagged)
  repeated uint32 trunks = 3;
  string vlan_mode = 4;
  string bond_mode = 5;
  repeated OvsdbInterface interfaces = 6;
}

// RFC 7047 Interface table
message OvsdbInterface {
  string name = 1;
  string type = 2;      // "system" | "internal" | "patch" | "vxlan" | ...
  string mac_in_use = 3;
  string mac = 4;
  string admin_state = 5;
  string link_state = 6;
  map<string, string> options = 7;  // tunnel options: remote_ip, local_ip, key
}

// =============================================================================
// Runtime Service - Live operational state
// =============================================================================

// Live runtime state: process info, services, system metrics.
// Not stored in any database — queried directly from the running system.
service RuntimeMirror {
  // Get overall system runtime info
  rpc GetSystemInfo(google.protobuf.Empty) returns (RuntimeGetSystemInfoResponse);

  // List dinit services and their states
  rpc ListServices(RuntimeListServicesRequest) returns (RuntimeListServicesResponse);

  // Get a specific service's state
  rpc GetService(RuntimeGetServiceRequest) returns (RuntimeServiceInfo);

  // Stream live metric updates (CPU, memory, network counters)
  rpc StreamMetrics(RuntimeStreamMetricsRequest) returns (stream RuntimeMetricUpdate);

  // Get network interface states (from rtnetlink)
  rpc ListInterfaces(google.protobuf.Empty) returns (RuntimeListInterfacesResponse);

  // Get NUMA topology
  rpc GetNumaTopology(google.protobuf.Empty) returns (RuntimeGetNumaTopologyResponse);
}

// --- Runtime Messages ---

message RuntimeGetSystemInfoResponse {
  string hostname = 1;
  string kernel_version = 2;
  uint64 uptime_seconds = 3;
  uint64 boot_timestamp = 4;
  uint32 cpu_count = 5;
  uint64 memory_total_bytes = 6;
  uint64 memory_available_bytes = 7;
  uint64 memory_used_bytes = 8;
  string init_system = 9;            // "dinit" | "systemd"
  string arch = 10;                  // "x86_64" | "aarch64"
  google.protobuf.Timestamp queried_at = 11;
}

message RuntimeListServicesRequest {
  // Filter by state (empty = all)
  string state_filter = 1;
}

message RuntimeListServicesResponse {
  repeated RuntimeServiceInfo services = 1;
}

message RuntimeGetServiceRequest {
  string service_name = 1;
}

message RuntimeServiceInfo {
  string name = 1;
  string state = 2;           // "STARTED" | "STOPPED" | "STARTING" | "STOPPING"
  uint32 pid = 3;
  bool enabled = 4;
  string description = 5;
  repeated string dependencies = 6;
  google.protobuf.Timestamp started_at = 7;
}

message RuntimeStreamMetricsRequest {
  // Interval in seconds between updates (default: 5)
  uint32 interval_seconds = 1;
  // Which metric categories to include (empty = all)
  repeated string categories = 2;   // "cpu" | "memory" | "network" | "disk"
}

message RuntimeMetricUpdate {
  string category = 1;
  string name = 2;
  double value = 3;
  string unit = 4;
  map<string, string> labels = 5;   // e.g. {"interface": "ens3", "direction": "rx"}
  google.protobuf.Timestamp timestamp = 6;
}

message RuntimeListInterfacesResponse {
  repeated RuntimeNetworkInterface interfaces = 1;
}

message RuntimeNetworkInterface {
  string name = 1;
  uint32 index = 2;
  string mac_address = 3;
  string state = 4;           // "UP" | "DOWN" | "UNKNOWN"
  uint32 mtu = 5;
  repeated string ipv4_addresses = 6;
  repeated string ipv6_addresses = 7;
  uint64 rx_bytes = 8;
  uint64 tx_bytes = 9;
  uint64 rx_packets = 10;
  uint64 tx_packets = 11;
  string driver = 12;
  uint32 speed_mbps = 13;
}

message RuntimeGetNumaTopologyResponse {
  repeated NumaNode nodes = 1;
}

message NumaNode {
  uint32 node_id = 1;
  repeated uint32 cpus = 2;
  uint64 memory_total_bytes = 3;
  uint64 memory_free_bytes = 4;
  uint64 memory_used_bytes = 5;
}

// =============================================================================
// D-Bus Passthrough Service
// =============================================================================

// Generic D-Bus method call passthrough. Allows gRPC-Web clients (browser UI)
// to invoke any method on any D-Bus interface reachable from the session or
// system bus. This is the extension point for services that register on the
// bus (e.g. ai.assistant.v1) without needing dedicated gRPC proto definitions.
service DbusPassthrough {
  // Call a D-Bus method and return the JSON result.
  rpc Call(DbusCallRequest) returns (dbusCallResponse);

  // Get a D-Bus property value as JSON.
  rpc Get(DbusGetPropertyRequest) returns (DbusGetPropertyResponse);

  // Set a D-Bus property value from JSON.
  rpc Set(DbusSetPropertyRequest) returns (DbusSetPropertyResponse);

  // Subscribe to a D-Bus signal, streaming events as JSON.
  rpc Watch(DbusWatchRequest) returns (stream DbusSignalEvent);
}

message DbusCallRequest {
  string bus = 1;            // "session" | "system"
  string destination = 2;    // e.g. "ai.assistant.v1"
  string path = 3;           // e.g. "/ai/assistant"
  string interface = 4;      // e.g. "ai.assistant.v1"
  string method = 5;         // e.g. "GetSoulMemory"
  string json_body = 6;      // JSON-encoded argument(s)
}

message dbusCallResponse {
  bool success = 1;
  string json_result = 2;    // JSON-encoded return value
  string error = 3;          // error message if failed
}

message DbusGetPropertyRequest {
  string bus = 1;
  string destination = 2;
  string path = 3;
  string interface = 4;
  string property = 5;
}

message DbusGetPropertyResponse {
  bool success = 1;
  string json_value = 2;
  string error = 3;
}

message DbusSetPropertyRequest {
  string bus = 1;
  string destination = 2;
  string path = 3;
  string interface = 4;
  string property = 5;
  string json_value = 6;
}

message DbusSetPropertyResponse {
  bool success = 1;
  string error = 2;
}

message DbusWatchRequest {
  string bus = 1;
  string destination = 2;
  string path = 3;
  string interface = 4;
  repeated string signal_names = 5;  // empty = all signals
}

message DbusSignalEvent {
  string signal_name = 1;
  string path = 2;
  string interface = 3;
  string json_body = 4;
  google.protobuf.Timestamp timestamp = 5;
}

// =============================================================================
// Zeroclaw projection (read-only gRPC view of the plugin's route/provider tree)
// subid: exp.service.zeroclaw-bridge.grpc-stream@v1
// =============================================================================

message ModelRouteProto {
  string hint = 1;
  string model = 2;
  string provider = 3;
  bool available = 4;
  string effort_level = 5;
  string privacy_tier = 6;
  uint32 context_window = 7;
}

message ProviderProto {
  string id = 1;
  string route = 2;
  string kind = 3;
}

message ZeroclawProjection {
  string schema_json = 1;
  repeated ModelRouteProto model_routes = 2;
  repeated ProviderProto providers = 3;
}

//! Typed gRPC reflection descriptors synthesized from `PluginSchema.methods`
//! (REQ-6.1): per-method `FileDescriptorProto`s with real field types derived
//! from `MethodDecl.args` / `MethodDecl.returns` JSON Schemas — never
//! `google.protobuf.Struct`.
//!
//! Naming follows the spec's acceptance criterion (Task 3.2):
//!
//! ```text
//! file:    operation/method/<plugin>/<method>.proto
//! package: operation.method.<plugin>.<method>
//! service: <Method>Service   rpc <Method>(<Method>Input) returns (<Method>Output)
//! ```
//!
//! The protobuf wire encoding is written by hand (varint + length-delimited
//! fields of descriptor.proto messages) so the crate stays dependency-free.
//! The bytes are a valid `google.protobuf.FileDescriptorSet` consumable by
//! tonic-reflection / grpcurl.

use crate::schema::{MethodDecl, PluginSchema};
use serde_json::Value as JVal;

// FieldDescriptorProto.Type values (descriptor.proto)
const T_DOUBLE: u64 = 1;
const T_INT64: u64 = 3;
const T_BOOL: u64 = 8;
const T_STRING: u64 = 9;
const T_MESSAGE: u64 = 11;
// FieldDescriptorProto.Label values
const L_OPTIONAL: u64 = 1;
const L_REPEATED: u64 = 3;

/// One synthesized per-method descriptor file plus its reflection index keys.
#[derive(Debug, Clone)]
pub struct MethodDescriptor {
    pub method_name: String,
    pub file_name: String,
    pub package: String,
    /// Fully-qualified service name, e.g. `operation.method.unix_socket.bind.BindService`.
    pub service_full: String,
    /// `/package.Service/Rpc` — the callable route path.
    pub grpc_path: String,
    pub input_full: String,
    pub output_full: String,
    /// All fully-qualified symbols this file defines (for symbol lookup).
    pub symbols: Vec<String>,
    /// Encoded `FileDescriptorProto` bytes.
    pub file_descriptor_proto: Vec<u8>,
}

/// Synthesize the full `FileDescriptorSet` for one plugin, one file per
/// method, sorted by method name for byte determinism (NFR-2).
pub fn descriptor_set_for_plugin(
    plugin_id: &str,
    schema: &PluginSchema,
) -> (Vec<u8>, Vec<MethodDescriptor>) {
    let mut names: Vec<&String> = schema.methods.keys().collect();
    names.sort();
    let mut infos = Vec::new();
    let mut set = Vec::new();
    for name in names {
        let info = method_file_descriptor(plugin_id, &schema.methods[name]);
        // FileDescriptorSet.file = 1 (repeated message)
        put_bytes(&mut set, 1, &info.file_descriptor_proto);
        infos.push(info);
    }
    (set, infos)
}

/// Build one per-method `FileDescriptorProto` with typed Input/Output messages.
pub fn method_file_descriptor(plugin_id: &str, method: &MethodDecl) -> MethodDescriptor {
    let snake = snake_case(&method.name);
    let pascal = pascal_case(&method.name);
    let package = format!("operation.method.{plugin_id}.{snake}");
    let file_name = format!("operation/method/{plugin_id}/{snake}.proto");

    let input_msg = message_from_json_schema(&format!("{pascal}Input"), &method.args);
    let empty = serde_json::json!({"type": "object"});
    let output_schema = method.returns.as_ref().unwrap_or(&empty);
    let output_msg = message_from_json_schema(&format!("{pascal}Output"), output_schema);

    let input_full = format!("{package}.{pascal}Input");
    let output_full = format!("{package}.{pascal}Output");
    let service_full = format!("{package}.{pascal}Service");

    // MethodDescriptorProto
    let mut m = Vec::new();
    put_str(&mut m, 1, &pascal);
    put_str(&mut m, 2, &format!(".{input_full}"));
    put_str(&mut m, 3, &format!(".{output_full}"));

    // ServiceDescriptorProto
    let mut svc = Vec::new();
    put_str(&mut svc, 1, &format!("{pascal}Service"));
    put_bytes(&mut svc, 2, &m);

    // FileDescriptorProto
    let mut file = Vec::new();
    put_str(&mut file, 1, &file_name);
    put_str(&mut file, 2, &package);
    put_bytes(&mut file, 4, &encode_message(&input_msg));
    put_bytes(&mut file, 4, &encode_message(&output_msg));
    put_bytes(&mut file, 6, &svc);
    put_str(&mut file, 12, "proto3");

    let mut symbols = vec![
        service_full.clone(),
        input_full.clone(),
        output_full.clone(),
    ];
    symbols.push(format!("{service_full}.{pascal}"));
    collect_nested_symbols(
        &input_msg,
        &format!("{package}.{}", input_msg.name),
        &mut symbols,
    );
    collect_nested_symbols(
        &output_msg,
        &format!("{package}.{}", output_msg.name),
        &mut symbols,
    );

    MethodDescriptor {
        method_name: method.name.clone(),
        grpc_path: format!("/{service_full}/{pascal}"),
        file_name,
        package,
        service_full,
        input_full,
        output_full,
        symbols,
        file_descriptor_proto: file,
    }
}

// ---------------------------------------------------------------------------
// JSON Schema -> DescriptorProto message synthesis
// ---------------------------------------------------------------------------

struct MessageDef {
    name: String,
    fields: Vec<FieldDef>,
    nested: Vec<MessageDef>,
}

struct FieldDef {
    name: String,
    number: u64,
    repeated: bool,
    proto_type: u64,
    /// Relative type name for `T_MESSAGE` fields (a nested message).
    type_name: Option<String>,
}

/// Walk a schemars JSON Schema document into a proto message definition.
/// Objects with properties become nested messages; scalars map directly;
/// enums/unknown/any degrade to string (JSON-encoded).
fn message_from_json_schema(msg_name: &str, schema: &JVal) -> MessageDef {
    let defs = schema
        .get("$defs")
        .or_else(|| schema.get("definitions"))
        .and_then(JVal::as_object);
    build_message(msg_name, resolve(schema, defs), defs)
}

fn build_message(
    name: &str,
    node: &JVal,
    defs: Option<&serde_json::Map<String, JVal>>,
) -> MessageDef {
    let mut fields = Vec::new();
    let mut nested = Vec::new();
    if let Some(props) = node.get("properties").and_then(JVal::as_object) {
        // serde_json Map is BTreeMap-backed: iteration (and thus field
        // numbering) is name-sorted and deterministic.
        for (i, (fname, fnode)) in props.iter().enumerate() {
            let number = (i + 1) as u64;
            let (repeated, item) = match unwrap_array(fnode, defs) {
                Some(item) => (true, item),
                None => (false, resolve(fnode, defs).clone()),
            };
            let (proto_type, type_name) = proto_type_of(&item, defs, fname, &mut nested);
            fields.push(FieldDef {
                name: fname.clone(),
                number,
                repeated,
                proto_type,
                type_name,
            });
        }
    }
    MessageDef {
        name: name.to_string(),
        fields,
        nested,
    }
}

/// If `node` is an array schema, return its resolved item schema.
fn unwrap_array(node: &JVal, defs: Option<&serde_json::Map<String, JVal>>) -> Option<JVal> {
    let node = resolve(node, defs);
    if json_type(node) == Some("array") {
        let item = node.get("items").map(|i| resolve(i, defs).clone());
        Some(item.unwrap_or(serde_json::json!({})))
    } else {
        None
    }
}

fn proto_type_of(
    node: &JVal,
    defs: Option<&serde_json::Map<String, JVal>>,
    field_name: &str,
    nested: &mut Vec<MessageDef>,
) -> (u64, Option<String>) {
    let node = resolve(node, defs);

    // Option<T>: collapse anyOf [T, null] to T.
    if let Some(alts) = node
        .get("anyOf")
        .or_else(|| node.get("oneOf"))
        .and_then(JVal::as_array)
    {
        let non_null: Vec<&JVal> = alts
            .iter()
            .filter(|a| json_type(a) != Some("null"))
            .collect();
        if let [single] = non_null.as_slice() {
            return proto_type_of(single, defs, field_name, nested);
        }
        // Multi-branch union: JSON-encoded string.
        return (T_STRING, None);
    }

    match json_type(node) {
        Some("string") => (T_STRING, None),
        Some("integer") => (T_INT64, None),
        Some("number") => (T_DOUBLE, None),
        Some("boolean") => (T_BOOL, None),
        Some("object") if node.get("properties").is_some() => {
            let msg_name = format!("{}Msg", pascal_case(field_name));
            let def = build_message(&msg_name, node, defs);
            nested.push(def);
            (T_MESSAGE, Some(msg_name))
        }
        // enum / free-form object / any -> JSON-encoded string
        _ => (T_STRING, None),
    }
}

fn resolve<'a>(node: &'a JVal, defs: Option<&'a serde_json::Map<String, JVal>>) -> &'a JVal {
    if let (Some(r), Some(d)) = (node.get("$ref").and_then(JVal::as_str), defs) {
        if let Some(key) = r.rsplit('/').next() {
            if let Some(target) = d.get(key) {
                return resolve(target, defs);
            }
        }
    }
    node
}

fn json_type(node: &JVal) -> Option<&str> {
    match node.get("type") {
        Some(JVal::String(s)) => Some(s.as_str()),
        Some(JVal::Array(a)) => a.iter().filter_map(JVal::as_str).find(|t| *t != "null"),
        _ => None,
    }
}

fn collect_nested_symbols(msg: &MessageDef, full: &str, out: &mut Vec<String>) {
    for n in &msg.nested {
        let child = format!("{full}.{}", n.name);
        out.push(child.clone());
        collect_nested_symbols(n, &child, out);
    }
}

// ---------------------------------------------------------------------------
// descriptor.proto wire encoding
// ---------------------------------------------------------------------------

fn encode_message(def: &MessageDef) -> Vec<u8> {
    // DescriptorProto: name=1, field=2, nested_type=3
    let mut out = Vec::new();
    put_str(&mut out, 1, &def.name);
    for f in &def.fields {
        // FieldDescriptorProto: name=1, number=3, label=4, type=5, type_name=6, json_name=10
        let mut fd = Vec::new();
        put_str(&mut fd, 1, &f.name);
        put_varint_field(&mut fd, 3, f.number);
        put_varint_field(&mut fd, 4, if f.repeated { L_REPEATED } else { L_OPTIONAL });
        put_varint_field(&mut fd, 5, f.proto_type);
        if let Some(t) = &f.type_name {
            // Relative reference resolves against the enclosing scope.
            put_str(&mut fd, 6, t);
        }
        put_str(&mut fd, 10, &json_name(&f.name));
        put_bytes(&mut out, 2, &fd);
    }
    for n in &def.nested {
        put_bytes(&mut out, 3, &encode_message(n));
    }
    out
}

fn put_varint(out: &mut Vec<u8>, mut v: u64) {
    loop {
        let b = (v & 0x7f) as u8;
        v >>= 7;
        if v == 0 {
            out.push(b);
            break;
        }
        out.push(b | 0x80);
    }
}

fn put_tag(out: &mut Vec<u8>, field: u32, wire: u8) {
    put_varint(out, ((field as u64) << 3) | wire as u64);
}

fn put_varint_field(out: &mut Vec<u8>, field: u32, v: u64) {
    put_tag(out, field, 0);
    put_varint(out, v);
}

fn put_str(out: &mut Vec<u8>, field: u32, s: &str) {
    put_bytes(out, field, s.as_bytes());
}

fn put_bytes(out: &mut Vec<u8>, field: u32, b: &[u8]) {
    put_tag(out, field, 2);
    put_varint(out, b.len() as u64);
    out.extend_from_slice(b);
}

fn json_name(snake: &str) -> String {
    let mut out = String::new();
    let mut upper = false;
    for c in snake.chars() {
        if c == '_' {
            upper = true;
        } else if upper {
            out.extend(c.to_uppercase());
            upper = false;
        } else {
            out.push(c);
        }
    }
    out
}

pub fn pascal_case(s: &str) -> String {
    let mut out = String::new();
    let mut upper = true;
    for c in s.chars() {
        if c == '_' || c == '-' || c == '.' {
            upper = true;
        } else if upper {
            out.extend(c.to_uppercase());
            upper = false;
        } else {
            out.push(c);
        }
    }
    out
}

pub fn snake_case(s: &str) -> String {
    let mut out = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_uppercase() {
            if i > 0 && !out.ends_with('_') {
                out.push('_');
            }
            out.extend(c.to_lowercase());
        } else if c == '-' || c == '.' {
            out.push('_');
        } else {
            out.push(c);
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Minimal FileDescriptorSet decoding — enough for reflection indexing,
// catalog `file_by_filename`, and tests. Returns borrowed subslices of the
// input (zero-copy).
// ---------------------------------------------------------------------------

/// Summary of one file entry inside an encoded `FileDescriptorSet`, borrowing
/// the underlying descriptor bytes.
#[derive(Debug)]
pub struct FileSummary<'a> {
    pub name: String,
    pub package: String,
    pub messages: Vec<String>,
    pub services: Vec<String>,
    /// Borrowed `FileDescriptorProto` bytes within the set.
    pub bytes: &'a [u8],
}

/// Iterate the `file` entries of an encoded `FileDescriptorSet`.
pub fn decode_file_summaries(set: &[u8]) -> Result<Vec<FileSummary<'_>>, String> {
    let mut out = Vec::new();
    let mut r = Reader { buf: set, pos: 0 };
    while !r.done() {
        let (field, wire) = r.tag()?;
        if field == 1 && wire == 2 {
            let bytes = r.len_delim()?;
            out.push(decode_file_summary(bytes)?);
        } else {
            r.skip(wire)?;
        }
    }
    Ok(out)
}

fn decode_file_summary(bytes: &[u8]) -> Result<FileSummary<'_>, String> {
    let mut s = FileSummary {
        name: String::new(),
        package: String::new(),
        messages: Vec::new(),
        services: Vec::new(),
        bytes,
    };
    let mut r = Reader { buf: bytes, pos: 0 };
    while !r.done() {
        let (field, wire) = r.tag()?;
        match (field, wire) {
            (1, 2) => s.name = r.string()?,
            (2, 2) => s.package = r.string()?,
            (4, 2) => s.messages.push(first_string_field(r.len_delim()?)?),
            (6, 2) => s.services.push(first_string_field(r.len_delim()?)?),
            _ => r.skip(wire)?,
        }
    }
    Ok(s)
}

/// Read field #1 (name) of a DescriptorProto/ServiceDescriptorProto.
fn first_string_field(bytes: &[u8]) -> Result<String, String> {
    let mut r = Reader { buf: bytes, pos: 0 };
    while !r.done() {
        let (field, wire) = r.tag()?;
        if field == 1 && wire == 2 {
            return r.string();
        }
        r.skip(wire)?;
    }
    Ok(String::new())
}

struct Reader<'a> {
    buf: &'a [u8],
    pos: usize,
}

impl<'a> Reader<'a> {
    fn done(&self) -> bool {
        self.pos >= self.buf.len()
    }

    fn varint(&mut self) -> Result<u64, String> {
        let mut v = 0u64;
        let mut shift = 0;
        loop {
            let b = *self
                .buf
                .get(self.pos)
                .ok_or_else(|| "varint overruns buffer".to_string())?;
            self.pos += 1;
            v |= ((b & 0x7f) as u64) << shift;
            if b & 0x80 == 0 {
                return Ok(v);
            }
            shift += 7;
            if shift > 63 {
                return Err("varint too long".into());
            }
        }
    }

    fn tag(&mut self) -> Result<(u32, u8), String> {
        let t = self.varint()?;
        Ok(((t >> 3) as u32, (t & 7) as u8))
    }

    fn len_delim(&mut self) -> Result<&'a [u8], String> {
        let len = self.varint()? as usize;
        let end = self.pos + len;
        if end > self.buf.len() {
            return Err("length-delimited field overruns buffer".into());
        }
        let s = &self.buf[self.pos..end];
        self.pos = end;
        Ok(s)
    }

    fn string(&mut self) -> Result<String, String> {
        Ok(String::from_utf8_lossy(self.len_delim()?).into_owned())
    }

    fn skip(&mut self, wire: u8) -> Result<(), String> {
        match wire {
            0 => {
                self.varint()?;
            }
            1 => self.pos += 8,
            2 => {
                self.len_delim()?;
            }
            5 => self.pos += 4,
            w => return Err(format!("unsupported wire type {w}")),
        }
        if self.pos > self.buf.len() {
            return Err("skip overruns buffer".into());
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::adapter::{method_decl_from_schemars_with_output, AckOutput};
    use crate::schema::SideEffect;
    use serde::{Deserialize, Serialize};

    #[derive(Serialize, Deserialize, schemars::JsonSchema)]
    struct SetDeviceInput {
        interface: String,
        private_key: String,
        listen_port: Option<u16>,
        fwmark: Option<u32>,
    }

    #[test]
    fn typed_descriptor_matches_spec_naming() {
        let decl = method_decl_from_schemars_with_output::<SetDeviceInput, AckOutput>(
            "set_device",
            SideEffect::Mutation,
            false,
            "wireguard.write",
            "mut.network.wireguard.set-device@v1",
        );
        let d = method_file_descriptor("wireguard", &decl);
        assert_eq!(d.package, "operation.method.wireguard.set_device");
        assert_eq!(
            d.service_full,
            "operation.method.wireguard.set_device.SetDeviceService"
        );
        assert_eq!(
            d.input_full,
            "operation.method.wireguard.set_device.SetDeviceInput"
        );
        assert_eq!(
            d.grpc_path,
            "/operation.method.wireguard.set_device.SetDeviceService/SetDevice"
        );

        // Round-trip through the wire decoder: real typed messages, no Struct.
        let mut set = Vec::new();
        put_bytes(&mut set, 1, &d.file_descriptor_proto);
        let files = decode_file_summaries(&set).unwrap();
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].name, "operation/method/wireguard/set_device.proto");
        assert_eq!(files[0].services, vec!["SetDeviceService"]);
        assert_eq!(files[0].messages, vec!["SetDeviceInput", "SetDeviceOutput"]);
    }

    #[test]
    fn case_conversions() {
        assert_eq!(pascal_case("set_device"), "SetDevice");
        assert_eq!(snake_case("SetDevice"), "set_device");
        assert_eq!(json_name("listen_port"), "listenPort");
    }
}

//! `PluginObjectBlob` — the sealed, self-describing projection of one
//! `PluginSchema` into one runtime identity (whitepaper "Target Data Model").
//!
//! The blob couples the four identities that must not drift:
//! schema identity (canonical JSON + sha256), D-Bus identity, gRPC identity,
//! and the reflection descriptor identity. It is deliberately redundant at the
//! blob boundary: schema stays authoritative, but the blob is self-describing
//! enough that reflection, GUI, compliance, and dispatch reason about the same
//! object without reassembling identity from scattered files.
//!
//! ## Sealed byte format (zero-copy)
//!
//! ```text
//! offset  size  content
//! 0       8     magic "OPBLOB01"
//! 8       2     format version (u16 LE) = 1
//! 10      2     section count (u16 LE)
//! 12      4     reserved
//! 16      32    sha256 of the SCHEMA_JSON section (the schema hash)
//! 48      16    reserved
//! 64      24*n  section table: tag u32, reserved u32, offset u64, len u64
//! ...           8-byte-aligned section payloads
//! ```
//!
//! Sections: 1 = canonical `PluginSchema` JSON, 2 = `BlobManifest` JSON,
//! 3 = protobuf `FileDescriptorSet`, 4 = compliance/extra metadata JSON.
//!
//! `BlobRef` verifies magic + hash once, then hands out borrowed slices —
//! reads never copy or re-parse the payload. Sealed bytes are fully
//! deterministic for the same schema (sorted maps, no timestamps), so the
//! schema hash doubles as the artifact identity in the filename:
//! `<plugin_id>.<hash16>.blob`.

use crate::descriptor;
use crate::schema::{hex, PluginSchema, SideEffect};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::io;
use std::path::{Path, PathBuf};

pub const MAGIC: &[u8; 8] = b"OPBLOB01";
pub const FORMAT_VERSION: u16 = 1;

pub const SECTION_SCHEMA_JSON: u32 = 1;
pub const SECTION_MANIFEST_JSON: u32 = 2;
pub const SECTION_DESCRIPTOR_SET: u32 = 3;
pub const SECTION_META_JSON: u32 = 4;

const HEADER_LEN: usize = 64;
const SECTION_ENTRY_LEN: usize = 24;

/// D-Bus identity carried by the blob (REQ-7.1/7.2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DbusIdentity {
    pub bus_name: String,
    pub object_path: String,
    pub interface_name: String,
}

/// gRPC identity: per-method packages/services synthesized from the schema.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct GrpcIdentity {
    /// Fully-qualified service names, sorted.
    pub services: Vec<String>,
    /// Descriptor file names, sorted (parallel to services).
    pub files: Vec<String>,
}

/// Per-method manifest entry copied from `PluginSchema.methods` plus the
/// synthesized gRPC identity — the compliance/audit unit.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MethodManifest {
    pub schema_name: String,
    pub grpc_name: String,
    pub grpc_path: String,
    pub grpc_service: String,
    pub grpc_file: String,
    pub input_message: String,
    pub output_message: String,
    pub subid: String,
    pub required_capability: Option<String>,
    pub side_effect: SideEffect,
    pub idempotent: bool,
    /// Fully-qualified symbols the method's descriptor file defines.
    pub symbols: Vec<String>,
}

/// The blob's self-describing metadata (section 2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BlobManifest {
    /// Runtime blob class. Serialized as `type` so the store can hold active
    /// reflection blobs now and other blob families later without guessing.
    #[serde(rename = "type", default = "default_blob_type")]
    pub blob_type: String,
    pub plugin_id: String,
    pub schema_version: String,
    pub schema_hash: String,
    pub dbus: DbusIdentity,
    pub grpc: GrpcIdentity,
    /// WireGuard-keypair identity of the publishing account (public half
    /// only); its session persists for the life of the account.
    #[serde(default)]
    pub identity: Option<crate::identity::BlobIdentity>,
    pub methods: Vec<MethodManifest>,
}

fn default_blob_type() -> String {
    "active_reflection".to_string()
}

/// Owned, unsealed blob. `seal()` produces the immutable byte image.
#[derive(Debug, Clone)]
pub struct PluginObjectBlob {
    pub manifest: BlobManifest,
    /// Canonical `PluginSchema` JSON (the authoritative contract bytes).
    pub schema_json: String,
    /// Encoded `google.protobuf.FileDescriptorSet` for all plugin methods.
    pub descriptor_set: Vec<u8>,
    /// Compliance / extra metadata (subids, immutable paths, dialect …).
    pub meta_json: String,
}

/// Canonical D-Bus path form: lowercase, hyphens -> underscores.
pub fn canonical_plugin_id(name: &str) -> String {
    name.to_lowercase().replace('-', "_")
}

/// Freeze one `PluginSchema` into a `PluginObjectBlob` (whitepaper "Blob
/// Creation Pipeline" steps 3–9). The schema is the input and stays the
/// authority; nothing here invents contract data.
pub fn blobify(schema: &PluginSchema) -> PluginObjectBlob {
    blobify_with_identity(schema, None)
}

/// `blobify`, stamping the publishing account's WireGuard-keypair identity
/// (public half only) into the manifest.
pub fn blobify_with_identity(
    schema: &PluginSchema,
    identity: Option<crate::identity::BlobIdentity>,
) -> PluginObjectBlob {
    blobify_canonical(schema, schema.canonical_json(), identity)
}

/// `blobify` with the sealed canonical JSON supplied by the caller.
///
/// This is the lossless path for the workspace's authoritative
/// `op_state_store::PluginSchema`: the caller serializes the FULL canonical
/// type (signals, guarantees, category, …) and `schema` is only the reduced
/// working view this crate needs for descriptor synthesis. The sealed
/// SCHEMA_JSON section — and therefore the schema hash — covers the complete
/// contract, never a reduced projection of it.
pub fn blobify_canonical(
    schema: &PluginSchema,
    schema_json: String,
    identity: Option<crate::identity::BlobIdentity>,
) -> PluginObjectBlob {
    let plugin_id = canonical_plugin_id(&schema.name);
    let schema_hash = {
        let mut h = Sha256::new();
        h.update(schema_json.as_bytes());
        hex(&h.finalize())
    };

    let (descriptor_set, method_infos) = descriptor::descriptor_set_for_plugin(&plugin_id, schema);

    let mut methods: Vec<MethodManifest> = method_infos
        .iter()
        .map(|d| {
            let decl = schema
                .methods
                .get(&d.method_name)
                .or_else(|| schema.methods.values().find(|m| m.name == d.method_name))
                .expect("descriptor method must come from PluginSchema.methods");
            MethodManifest {
                schema_name: decl.name.clone(),
                grpc_name: descriptor::pascal_case(&decl.name),
                grpc_path: d.grpc_path.clone(),
                grpc_service: d.service_full.clone(),
                grpc_file: d.file_name.clone(),
                input_message: d.input_full.clone(),
                output_message: d.output_full.clone(),
                subid: decl.subid.clone(),
                required_capability: decl.required_capability.clone(),
                side_effect: decl.side_effect,
                idempotent: decl.idempotent,
                symbols: d.symbols.clone(),
            }
        })
        .collect();
    methods.sort_by(|a, b| a.schema_name.cmp(&b.schema_name));

    let mut services: Vec<String> = methods.iter().map(|m| m.grpc_service.clone()).collect();
    services.sort();
    let mut files: Vec<String> = methods.iter().map(|m| m.grpc_file.clone()).collect();
    files.sort();

    let manifest = BlobManifest {
        blob_type: default_blob_type(),
        plugin_id: plugin_id.clone(),
        schema_version: schema.version.clone(),
        schema_hash,
        dbus: DbusIdentity {
            bus_name: "org.opdbus.v1.plugins".to_string(),
            object_path: format!("/org/opdbus/v1/plugins/{plugin_id}"),
            interface_name: "org.opdbus.v1.Plugin".to_string(),
        },
        grpc: GrpcIdentity { services, files },
        identity,
        methods,
    };

    let meta = serde_json::json!({
        "blob_format": FORMAT_VERSION,
        "dialect": schema.dialect,
        "subids": schema.subids,
        "immutable_paths": schema.immutable_paths,
        "json_schema": schema.to_json_schema(),
    });

    PluginObjectBlob {
        manifest,
        schema_json,
        descriptor_set,
        meta_json: serde_json::to_string(&meta).expect("meta serializes"),
    }
}

impl PluginObjectBlob {
    /// Rehydrate an owned blob from sealed bytes (inverse of `seal`).
    /// `schema_json` is copied verbatim, so `from_sealed(b).seal() == b`
    /// and the schema hash is preserved.
    pub fn from_sealed(bytes: &[u8]) -> Result<Self, String> {
        let r = BlobRef::new(bytes)?;
        Ok(Self {
            manifest: r.manifest()?,
            schema_json: r.schema_json().to_string(),
            descriptor_set: r.descriptor_set().to_vec(),
            meta_json: r.meta_json().unwrap_or("{}").to_string(),
        })
    }

    /// Seal into the immutable byte image. Deterministic: same schema, same bytes.
    pub fn seal(&self) -> Vec<u8> {
        let manifest_json =
            serde_json::to_string(&serde_json::to_value(&self.manifest).unwrap()).unwrap();
        let sections: [(u32, &[u8]); 4] = [
            (SECTION_SCHEMA_JSON, self.schema_json.as_bytes()),
            (SECTION_MANIFEST_JSON, manifest_json.as_bytes()),
            (SECTION_DESCRIPTOR_SET, &self.descriptor_set),
            (SECTION_META_JSON, self.meta_json.as_bytes()),
        ];

        let table_len = sections.len() * SECTION_ENTRY_LEN;
        let mut offset = align8(HEADER_LEN + table_len);
        let mut entries = Vec::with_capacity(sections.len());
        for (tag, bytes) in &sections {
            entries.push((*tag, offset as u64, bytes.len() as u64));
            offset = align8(offset + bytes.len());
        }

        let mut out = Vec::with_capacity(offset);
        out.extend_from_slice(MAGIC);
        out.extend_from_slice(&FORMAT_VERSION.to_le_bytes());
        out.extend_from_slice(&(sections.len() as u16).to_le_bytes());
        out.extend_from_slice(&[0u8; 4]);
        let mut h = Sha256::new();
        h.update(self.schema_json.as_bytes());
        out.extend_from_slice(&h.finalize());
        out.extend_from_slice(&[0u8; 16]);
        debug_assert_eq!(out.len(), HEADER_LEN);

        for (tag, off, len) in &entries {
            out.extend_from_slice(&tag.to_le_bytes());
            out.extend_from_slice(&[0u8; 4]);
            out.extend_from_slice(&off.to_le_bytes());
            out.extend_from_slice(&len.to_le_bytes());
        }

        for ((_, bytes), (_, off, _)) in sections.iter().zip(&entries) {
            while out.len() < *off as usize {
                out.push(0);
            }
            out.extend_from_slice(bytes);
        }
        out
    }

    /// `<plugin_id>.<hash16>.blob` — hash-addressed filename (shm layout).
    pub fn file_name(&self) -> String {
        format!(
            "{}.{}.blob",
            self.manifest.plugin_id,
            &self.manifest.schema_hash[..16]
        )
    }

    /// Atomic write: seal to `<name>.blob.tmp`, then rename over the final
    /// path. Readers scanning the directory never observe a partial blob
    /// (`.tmp` fails the `.blob` extension filter; rename(2) is atomic on
    /// the same filesystem).
    pub fn write_to_dir(&self, dir: &Path) -> io::Result<PathBuf> {
        std::fs::create_dir_all(dir)?;
        let path = dir.join(self.file_name());
        let tmp = dir.join(format!("{}.tmp", self.file_name()));
        std::fs::write(&tmp, self.seal())?;
        std::fs::rename(&tmp, &path)?;
        Ok(path)
    }
}

fn align8(n: usize) -> usize {
    (n + 7) & !7
}

/// Zero-copy view over sealed blob bytes. Construction verifies magic,
/// bounds, and the schema hash once; accessors return borrowed slices.
pub struct BlobRef<'a> {
    bytes: &'a [u8],
    sections: Vec<(u32, usize, usize)>,
}

impl<'a> BlobRef<'a> {
    pub fn new(bytes: &'a [u8]) -> Result<Self, String> {
        if bytes.len() < HEADER_LEN || &bytes[..8] != MAGIC {
            return Err("not an OPBLOB01 blob".into());
        }
        let version = u16::from_le_bytes([bytes[8], bytes[9]]);
        if version != FORMAT_VERSION {
            return Err(format!("unsupported blob format version {version}"));
        }
        let count = u16::from_le_bytes([bytes[10], bytes[11]]) as usize;
        let table_end = HEADER_LEN + count * SECTION_ENTRY_LEN;
        if bytes.len() < table_end {
            return Err("section table overruns blob".into());
        }
        let mut sections = Vec::with_capacity(count);
        for i in 0..count {
            let e = HEADER_LEN + i * SECTION_ENTRY_LEN;
            let tag = u32::from_le_bytes(bytes[e..e + 4].try_into().unwrap());
            let off = u64::from_le_bytes(bytes[e + 8..e + 16].try_into().unwrap()) as usize;
            let len = u64::from_le_bytes(bytes[e + 16..e + 24].try_into().unwrap()) as usize;
            if off + len > bytes.len() {
                return Err(format!("section {tag} overruns blob"));
            }
            sections.push((tag, off, len));
        }
        let blob = Self { bytes, sections };

        // Verify schema hash (blob-drift guard).
        let schema = blob
            .section(SECTION_SCHEMA_JSON)
            .ok_or("missing schema section")?;
        let mut h = Sha256::new();
        h.update(schema);
        if h.finalize().as_slice() != &bytes[16..48] {
            return Err("schema hash mismatch: blob is corrupt or tampered".into());
        }
        Ok(blob)
    }

    fn section(&self, tag: u32) -> Option<&'a [u8]> {
        self.sections
            .iter()
            .find(|(t, _, _)| *t == tag)
            .map(|(_, off, len)| &self.bytes[*off..*off + *len])
    }

    /// Canonical `PluginSchema` JSON — borrowed, zero-copy.
    pub fn schema_json(&self) -> &'a str {
        std::str::from_utf8(self.section(SECTION_SCHEMA_JSON).unwrap())
            .expect("schema section is UTF-8")
    }

    pub fn manifest_json(&self) -> &'a str {
        std::str::from_utf8(self.section(SECTION_MANIFEST_JSON).unwrap())
            .expect("manifest section is UTF-8")
    }

    /// Encoded `FileDescriptorSet` — borrowed, zero-copy; slices of this can
    /// be served directly to reflection clients.
    pub fn descriptor_set(&self) -> &'a [u8] {
        self.section(SECTION_DESCRIPTOR_SET).unwrap_or(&[])
    }

    pub fn meta_json(&self) -> Option<&'a str> {
        self.section(SECTION_META_JSON)
            .and_then(|b| std::str::from_utf8(b).ok())
    }

    pub fn schema_hash_hex(&self) -> String {
        hex(&self.bytes[16..48])
    }

    /// Parse the manifest (the one intentional allocation on the read path;
    /// everything else stays borrowed).
    pub fn manifest(&self) -> Result<BlobManifest, String> {
        serde_json::from_str(self.manifest_json()).map_err(|e| format!("manifest parse: {e}"))
    }

    /// Reconstruct the authoritative `PluginSchema` from the sealed bytes.
    ///
    /// This is the reduced working view; blobs sealed via
    /// `blobify_plugin_schema` carry the full workspace schema — use
    /// [`Self::state_store_schema`] to read it without loss.
    pub fn plugin_schema(&self) -> Result<PluginSchema, String> {
        serde_json::from_str(self.schema_json()).map_err(|e| format!("schema parse: {e}"))
    }

    /// Reconstruct the FULL canonical `op_state_store::PluginSchema`
    /// (signals, guarantees, category, …) from the sealed bytes. The plugin
    /// IS this schema; consumers must read it from here, never from a
    /// registry or a monolith file.
    pub fn state_store_schema(&self) -> Result<op_state_store::PluginSchema, String> {
        serde_json::from_str(self.schema_json()).map_err(|e| format!("schema parse: {e}"))
    }
}

//! Per-Method gRPC Reflection Integration
//!
//! This module integrates per-method typed gRPC services with reflection.
//! When a D-Bus object is created for a plugin, each of its methods gets its
//! own gRPC service generated and registered with the reflection service so
//! clients can discover the exact typed methods.

use std::collections::HashMap;
use std::sync::Arc;

use op_state_store::PluginSchema;
use prost::Message;
use prost_types::FileDescriptorSet;
use tokio::sync::RwLock;

/// Per-method service configuration for reflection.
#[derive(Clone)]
pub struct PerMethodReflectionConfig {
    /// Whether to enable per-method reflection
    pub enabled: bool,
    /// Base package name for method services
    pub base_package: String,
}

impl Default for PerMethodReflectionConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            base_package: "operation.method".to_string(),
        }
    }
}

/// Manages per-method gRPC service metadata for reflection.
///
/// This keeps track of which methods have been registered for gRPC and their
/// schemas, so the reflection service can advertise them correctly.
#[derive(Default)]
pub struct PerMethodReflectionRegistry {
    /// method_path -> MethodServiceMeta
    services: Arc<RwLock<HashMap<String, MethodReflectionMeta>>>,
}

/// Metadata about a registered method gRPC service.
#[derive(Clone, Debug)]
pub struct MethodReflectionMeta {
    /// Full method path: "plugin_id.method_name"
    pub method_path: String,
    /// Plugin ID (e.g., "zeroclaw")
    pub plugin_id: String,
    /// Method name (e.g., "RegisterAgent")
    pub method_name: String,
    /// gRPC service name (e.g., "RegisterAgentService")
    pub service_name: String,
    /// Schema version when registered
    pub schema_version: String,
    /// subid for this method
    pub subid: String,
    /// Required capability (if any)
    pub required_capability: Option<String>,
    /// When registered
    pub registered_at: std::time::Instant,
}

impl PerMethodReflectionRegistry {
    /// Create a new registry.
    pub fn new() -> Self {
        Self::default()
    }

    /// Register a method's gRPC service metadata.
    pub async fn register(
        &self,
        plugin_id: String,
        method_name: String,
        subid: String,
        required_capability: Option<String>,
        schema_version: String,
    ) -> MethodReflectionMeta {
        let method_path = format!("{}.{}", plugin_id, method_name);
        let service_name = to_method_service_name(&method_name);

        let meta = MethodReflectionMeta {
            method_path: method_path.clone(),
            plugin_id: plugin_id.clone(),
            method_name: method_name.clone(),
            service_name,
            schema_version: schema_version.clone(),
            subid,
            required_capability,
            registered_at: std::time::Instant::now(),
        };

        let mut services = self.services.write().await;
        services.insert(method_path, meta.clone());

        meta
    }

    /// Get metadata for a method.
    pub async fn get(&self, method_path: &str) -> Option<MethodReflectionMeta> {
        let services = self.services.read().await;
        services.get(method_path).cloned()
    }

    /// Get all methods for a plugin.
    pub async fn get_for_plugin(&self, plugin_id: &str) -> Vec<MethodReflectionMeta> {
        let services = self.services.read().await;
        services
            .values()
            .filter(|m| m.plugin_id == plugin_id)
            .cloned()
            .collect()
    }

    /// List all registered method services.
    pub async fn list(&self) -> Vec<MethodReflectionMeta> {
        let services = self.services.read().await;
        services.values().cloned().collect()
    }

    /// List all registered plugin IDs.
    pub async fn list_plugins(&self) -> Vec<String> {
        let services = self.services.read().await;
        let mut plugins: Vec<String> = services.values().map(|m| m.plugin_id.clone()).collect();
        plugins.sort();
        plugins.dedup();
        plugins
    }

    /// Unregister a method's gRPC service.
    pub async fn unregister(&self, method_path: &str) -> bool {
        let mut services = self.services.write().await;
        services.remove(method_path).is_some()
    }

    /// Unregister all methods for a plugin.
    pub async fn unregister_plugin(&self, plugin_id: &str) -> usize {
        let mut services = self.services.write().await;
        let to_remove: Vec<String> = services
            .iter()
            .filter(|(_, m)| m.plugin_id == plugin_id)
            .map(|(k, _)| k.clone())
            .collect();

        let count = to_remove.len();
        for key in to_remove {
            services.remove(&key);
        }

        count
    }
}

/// Convert a method name to a gRPC service name.
///
/// Examples:
///   - "RegisterAgent" -> "RegisterAgentService"
///   - "report_status" -> "Report_statusService"
///   - "ReceiveCommand" -> "ReceiveCommandService"
pub fn to_method_service_name(method_name: &str) -> String {
    let mut chars = method_name.chars();
    match chars.next() {
        None => String::new(),
        Some(c) => format!(
            "{}Service",
            c.to_uppercase().chain(chars).collect::<String>()
        ),
    }
}

/// Generate reflection file descriptor bytes for all registered methods.
///
/// This creates a combined FileDescriptorSet that can be registered with
/// tonic-reflection to expose all per-method services.
pub fn generate_reflection_file_descriptor_set(schemas: &HashMap<String, PluginSchema>) -> Vec<u8> {
    let mut set = FileDescriptorSet::default();
    let mut plugin_ids = schemas.keys().collect::<Vec<_>>();
    plugin_ids.sort();

    for plugin_id in plugin_ids {
        let Some(schema) = schemas.get(plugin_id) else {
            continue;
        };
        for (method_name, method_decl) in &schema.methods {
            let bytes = crate::plugin_grpc_gen::generate_method_file_descriptor(
                plugin_id,
                method_name,
                method_decl,
            );
            if bytes.is_empty() {
                continue;
            }
            if let Ok(mut method_set) = FileDescriptorSet::decode(bytes.as_slice()) {
                set.file.append(&mut method_set.file);
            }
        }
    }

    let mut bytes = Vec::new();
    if set.encode(&mut bytes).is_ok() {
        bytes
    } else {
        Vec::new()
    }
}

/// Generate all method protos as a combined string for a plugin.
pub fn generate_all_method_protos_for_plugin(plugin_id: &str, schema: &PluginSchema) -> String {
    crate::plugin_grpc_gen::generate_plugin_method_protos(plugin_id, schema)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_service_name_conversion() {
        assert_eq!(
            to_method_service_name("RegisterAgent"),
            "RegisterAgentService"
        );
        assert_eq!(
            to_method_service_name("report_status"),
            "Report_statusService"
        );
        assert_eq!(
            to_method_service_name("ReceiveCommand"),
            "ReceiveCommandService"
        );
    }

    #[tokio::test]
    async fn test_register_and_list() {
        let registry = PerMethodReflectionRegistry::new();

        let meta = registry
            .register(
                "zeroclaw".to_string(),
                "RegisterAgent".to_string(),
                "exp.service.zeroclaw.register-agent@v1".to_string(),
                Some("register".to_string()),
                "1.0.0".to_string(),
            )
            .await;

        assert_eq!(meta.plugin_id, "zeroclaw");
        assert_eq!(meta.method_name, "RegisterAgent");
        assert_eq!(meta.service_name, "RegisterAgentService");
        assert_eq!(meta.method_path, "zeroclaw.RegisterAgent");
        assert_eq!(meta.schema_version, "1.0.0");

        let list = registry.list().await;
        assert_eq!(list.len(), 1);
        assert_eq!(list[0].method_name, "RegisterAgent");
    }

    #[tokio::test]
    async fn test_get_for_plugin() {
        let registry = PerMethodReflectionRegistry::new();

        registry
            .register(
                "zeroclaw".to_string(),
                "RegisterAgent".to_string(),
                "exp.1".to_string(),
                None,
                "1.0.0".to_string(),
            )
            .await;

        registry
            .register(
                "zeroclaw".to_string(),
                "ReportStatus".to_string(),
                "exp.2".to_string(),
                None,
                "1.0.0".to_string(),
            )
            .await;

        let methods = registry.get_for_plugin("zeroclaw").await;
        assert_eq!(methods.len(), 2);
    }

    #[tokio::test]
    async fn test_unregister_plugin() {
        let registry = PerMethodReflectionRegistry::new();

        registry
            .register(
                "zeroclaw".to_string(),
                "RegisterAgent".to_string(),
                "exp.1".to_string(),
                None,
                "1.0.0".to_string(),
            )
            .await;

        registry
            .register(
                "zeroclaw".to_string(),
                "ReportStatus".to_string(),
                "exp.2".to_string(),
                None,
                "1.0.0".to_string(),
            )
            .await;

        let removed = registry.unregister_plugin("zeroclaw").await;
        assert_eq!(removed, 2);

        let meta = registry.get("zeroclaw.RegisterAgent").await;
        assert!(meta.is_none());
    }

    #[tokio::test]
    async fn test_list_plugins() {
        let registry = PerMethodReflectionRegistry::new();

        registry
            .register(
                "zeroclaw".to_string(),
                "RegisterAgent".to_string(),
                "exp.1".to_string(),
                None,
                "1.0.0".to_string(),
            )
            .await;

        registry
            .register(
                "unix_socket".to_string(),
                "CreateSocket".to_string(),
                "exp.2".to_string(),
                None,
                "1.0.0".to_string(),
            )
            .await;

        let plugins = registry.list_plugins().await;
        assert_eq!(plugins.len(), 2);
        assert!(plugins.contains(&"zeroclaw".to_string()));
        assert!(plugins.contains(&"unix_socket".to_string()));
    }
}

//! Per-Method Typed gRPC Services - Frozen at D-Bus Object Creation
//!
//! This module generates typed gRPC services from plugin schemas at the moment
//! a D-Bus object is created. Each D-Bus method becomes its own gRPC service.
//! The services are "frozen" - they reflect the schema exactly as it existed
//! at creation time and never change.
//!
//! Architecture:
//! ```text
//!     SchemaEngine ──► PluginSchema ──► PerMethodGrpcService (frozen)
//!           │                               │
//!           │                               ▼
//!           │                    gRPC Reflection (one service per method)
//!           │                               │
//!           ▼                               ▼
//!      /dev/shm/opdbus/plugin-blobs  Dynamic gRPC dispatch per method
//! ```
//!
//! Each method gets its own gRPC service with a single RPC. The reflection
//! service shows the exact typed interface for each method.

use std::collections::HashMap;
use std::sync::Arc;

use op_state_store::{MethodDecl, PluginSchema};
use prost::Message;
use prost_types::{
    field_descriptor_proto, DescriptorProto, FieldDescriptorProto, FileDescriptorProto,
    FileDescriptorSet, MethodDescriptorProto, ServiceDescriptorProto,
};
use tokio::sync::{broadcast, RwLock};

/// Manages frozen per-method gRPC services.
///
/// Once a plugin's D-Bus object is created, each of its methods gets its own
/// gRPC service generated and frozen. This ensures stable API contracts for
/// clients - each method is independently versioned and typed.
pub struct PerMethodGrpcServices {
    /// method_path -> ServiceRegistry (e.g., "zeroclaw.RegisterAgent")
    services: Arc<RwLock<HashMap<String, MethodServiceRegistry>>>,
    /// Broadcast channel for service lifecycle events
    lifecycle_tx: broadcast::Sender<MethodServiceLifecycleEvent>,
    /// Frozen per-method descriptor set created alongside D-Bus object registration.
    descriptor_bytes: std::sync::RwLock<Vec<u8>>,
}

/// A frozen gRPC service for a single method.
#[derive(Clone)]
pub struct MethodServiceRegistry {
    /// Full method path: "plugin_id.method_name"
    pub method_path: String,
    /// Plugin ID (e.g., "zeroclaw")
    pub plugin_id: String,
    /// Method name (e.g., "RegisterAgent")
    pub method_name: String,
    /// Schema version when this service was created
    pub schema_version: String,
    /// The subid for this method
    pub subid: String,
    /// Input JSON Schema
    pub input_schema: simd_json::OwnedValue,
    /// Output JSON Schema  
    pub output_schema: simd_json::OwnedValue,
    /// Required capability (if any)
    pub required_capability: Option<String>,
    /// When this service was created
    pub frozen_at: std::time::Instant,
}

/// Events emitted when method services are created or removed.
#[derive(Clone, Debug)]
pub enum MethodServiceLifecycleEvent {
    Created {
        method_path: String,
        plugin_id: String,
    },
    Removed {
        method_path: String,
    },
}

impl PerMethodGrpcServices {
    /// Create a new registry.
    pub fn new() -> Arc<Self> {
        let (lifecycle_tx, _) = broadcast::channel(64);
        Arc::new(Self {
            services: Arc::new(RwLock::new(HashMap::new())),
            lifecycle_tx,
            descriptor_bytes: std::sync::RwLock::new(Vec::new()),
        })
    }

    /// Get the lifecycle event receiver.
    pub fn lifecycle_rx(&self) -> broadcast::Receiver<MethodServiceLifecycleEvent> {
        self.lifecycle_tx.subscribe()
    }

    /// Create frozen gRPC services for all methods in a plugin schema.
    ///
    /// This is called at D-Bus object creation time. Each method gets its own
    /// service - the services are frozen and will never change.
    pub async fn create_frozen_services(
        &self,
        plugin_id: String,
        schema: &PluginSchema,
    ) -> Result<Vec<MethodServiceRegistry>, anyhow::Error> {
        let mut registries = Vec::new();

        for (method_name, method_decl) in &schema.methods {
            let method_path = format!("{}.{}", plugin_id, method_name);

            let registry = MethodServiceRegistry {
                method_path: method_path.clone(),
                plugin_id: plugin_id.clone(),
                method_name: method_name.clone(),
                schema_version: schema.version.clone(),
                subid: method_decl.subid.clone(),
                input_schema: method_decl.args.clone(),
                output_schema: method_decl
                    .returns
                    .clone()
                    .unwrap_or_else(|| simd_json::json!({})),
                required_capability: method_decl.required_capability.clone(),
                frozen_at: std::time::Instant::now(),
            };

            // Store each method as its own service
            let mut services = self.services.write().await;
            services.insert(method_path.clone(), registry.clone());

            registries.push(registry.clone());

            // Emit lifecycle event
            let _ = self
                .lifecycle_tx
                .send(MethodServiceLifecycleEvent::Created {
                    method_path,
                    plugin_id: plugin_id.clone(),
                });
        }

        self.freeze_descriptor_set(plugin_id.as_str(), schema);

        Ok(registries)
    }

    fn freeze_descriptor_set(&self, plugin_id: &str, schema: &PluginSchema) {
        let mut set = self
            .descriptor_bytes
            .read()
            .ok()
            .and_then(|bytes| FileDescriptorSet::decode(bytes.as_slice()).ok())
            .unwrap_or_default();

        for (method_name, method_decl) in &schema.methods {
            if let Some(file) =
                generate_method_file_descriptor_proto(plugin_id, method_name, method_decl)
            {
                set.file.push(file);
            }
        }

        let mut bytes = Vec::new();
        if set.encode(&mut bytes).is_ok() {
            if let Ok(mut stored) = self.descriptor_bytes.write() {
                *stored = bytes;
            }
        }
    }

    /// Return the frozen FileDescriptorSet bytes for all registered method services.
    ///
    /// This is a static snapshot. It is produced when plugin methods are registered
    /// alongside D-Bus object creation and is not mutated by the reflection service.
    pub fn frozen_descriptor_set_bytes(&self) -> Vec<u8> {
        self.descriptor_bytes
            .read()
            .map(|bytes| bytes.clone())
            .unwrap_or_default()
    }

    /// Get a method service registry by method path.
    pub async fn get_service(&self, method_path: &str) -> Option<MethodServiceRegistry> {
        let services = self.services.read().await;
        services.get(method_path).cloned()
    }

    /// Get all services for a plugin.
    pub async fn get_services_for_plugin(&self, plugin_id: &str) -> Vec<MethodServiceRegistry> {
        let services = self.services.read().await;
        services
            .values()
            .filter(|r| r.plugin_id == plugin_id)
            .cloned()
            .collect()
    }

    /// List all registered method paths.
    pub async fn list_methods(&self) -> Vec<String> {
        let services = self.services.read().await;
        services.keys().cloned().collect()
    }

    /// List all plugins that have registered method services.
    pub async fn list_plugins(&self) -> Vec<String> {
        let services = self.services.read().await;
        let mut plugins: Vec<String> = services.values().map(|r| r.plugin_id.clone()).collect();
        plugins.sort();
        plugins.dedup();
        plugins
    }

    /// Remove all method services for a plugin when its D-Bus object is removed.
    pub async fn remove_services_for_plugin(&self, plugin_id: &str) -> usize {
        let mut services = self.services.write().await;
        let to_remove: Vec<String> = services
            .iter()
            .filter(|(_, r)| r.plugin_id == plugin_id)
            .map(|(k, _)| k.clone())
            .collect();

        let count = to_remove.len();
        for key in &to_remove {
            if let Some(registry) = services.remove(key) {
                let _ = self
                    .lifecycle_tx
                    .send(MethodServiceLifecycleEvent::Removed {
                        method_path: registry.method_path,
                    });
            }
        }

        count
    }
}

/// Default implementation for testing.
impl Default for PerMethodGrpcServices {
    fn default() -> Self {
        let (lifecycle_tx, _) = broadcast::channel(64);
        Self {
            services: Arc::new(RwLock::new(HashMap::new())),
            lifecycle_tx,
            descriptor_bytes: std::sync::RwLock::new(Vec::new()),
        }
    }
}

