/// Hydrate in-memory reflection from the sealed SHM blob catalog.
    ///
    /// The blob catalog IS the plugin registry: a restart must advertise the
    /// same plugin set that was sealed, without waiting for every plugin to
    /// re-register at runtime. Call once at server startup.
    ///
    /// This also populates the frozen descriptor set from blob SECTION_DESCRIPTOR_SET,
    /// which is the single authoritative source of typed gRPC descriptors per OD-32.
    pub async fn hydrate_reflection_from_shm(&self) -> usize {
        let store = match op_blob::BlobStore::open_default() {
            Ok(store) => store,
            Err(error) => {
                tracing::warn!(%error, "cannot open SHM blob catalog; reflection starts empty");
                return 0;
            }
        };
        let blobs = store.plugin_object_blobs();
        let count = blobs.len();

        // Freeze typed descriptors from blob SECTION_DESCRIPTOR_SET into the
        // per-method services registry, so reflection advertises them.
        for blob in &blobs {
            // The blob's descriptor_set (section 3) is the authoritative source.
            // It was synthesized from PluginSchema.methods at sealing time and
            // already contains valid FileDescriptorProto entries for each method.
            if !blob.descriptor_set.is_empty() {
                // Import the descriptor set bytes into the frozen registry.
                // PerMethodGrpcServices will index them for reflection.
                if let Err(e) = self
                    .per_method_services
                    .freeze_descriptor_set_from_blob(blob)
                {
                    tracing::warn!(plugin_id = %blob.manifest.plugin_id, %e, "failed to freeze blob descriptor set");
                }
            }
            self.active_reflection.upsert_blob(blob.clone().into()).await;
        }

        // Also register each method with the reflection registry using the blob's manifest.
        for blob in &blobs {
            for method in &blob.manifest.methods {
                self.per_method_reflection
                    .register_from_manifest(
                        blob.manifest.plugin_id.clone(),
                        method.grpc_name.clone(),
                        method.subid.clone(),
                        method.required_capability.clone(),
                        blob.manifest.schema_version.clone(),
                    )
                    .await;
            }
        }

        tracing::info!(count, "hydrated reflection from SHM blob catalog");
        count
    }

