/// Freeze all plugin method descriptors from the configured schema provider.
    ///
    /// tonic-reflection is immutable once mounted. This must run before
    /// `build_operation_routes` creates the reflection service.
    pub async fn freeze_plugin_method_reflection(&self) {
        for plugin in self.plugin_provider.list_plugins().await {
            let Some((schema_json, _, _)) = self.plugin_provider.get_schema(&plugin.id).await
            else {
                warn!(
                    plugin_id = %plugin.id,
                    "plugin schema missing while freezing gRPC reflection methods"
                );
                continue;
            };
            let Ok(schema) = serde_json::from_str::<PluginSchema>(&schema_json) else {
                warn!(
                    plugin_id = %plugin.id,
                    "plugin schema could not be parsed while freezing gRPC reflection methods"
                );
                continue;
            };
            if schema.methods.is_empty() {
                continue;
            }
            if let Err(error) = self
                .register_plugin_methods(plugin.id.clone(), &schema)
                .await
            {
                warn!(
                    plugin_id = %plugin.id,
                    %error,
                    "failed to freeze plugin method descriptors for gRPC reflection"
                );
            }
        }
    }

    /// Freeze descriptor set directly from a sealed plugin blob.
    ///
    /// This is the OD-32 path: the blob's SECTION_DESCRIPTOR_SET (section 3)
    /// is the single authoritative source of typed gRPC descriptors. The bridge
    /// reads them here instead of re-synthesizing from schema.
    pub fn freeze_descriptor_set_from_blob(&self, blob: &op_blob::PluginObjectBlob) -> anyhow::Result<()> {
        // Import the descriptor bytes into our frozen registry.
        // FileDescriptorSet::decode will parse the concatenated set from section 3.
        let descriptor_bytes = blob.descriptor_set.clone();
        if descriptor_bytes.is_empty() {
            return Ok(());
        }

        // Decode and merge into our descriptor set.
        let mut set = self
            .descriptor_bytes
            .read()
            .ok()
            .and_then(|bytes| FileDescriptorSet::decode(bytes.as_slice()).ok())
            .unwrap_or_default();

        if let Ok(mut method_set) = FileDescriptorSet::decode(descriptor_bytes.as_slice()) {
            set.file.append(&mut method_set.file);
        }

        // Serialize back and store.
        let mut bytes = Vec::new();
        if set.encode(&mut bytes).is_ok() {
            if let Ok(mut stored) = self.descriptor_bytes.write() {
                *stored = bytes;
            }
        }
        Ok(())
    }

