//! Export concatenated FileDescriptorSet from the SHM blob catalog.
//!
//! OD-32: UI codegen consumes the blob's SECTION_DESCRIPTOR_SET (section 3)
//! instead of hand-maintained proto files. This provides the single source of
//! truth for typed gRPC clients.
//!
//! Usage:
//!   `op-grpc-bridge export-descriptors --output=catalog.bin`
//!   Then: `protoc --descriptor_set_in=catalog.bin --ts_out=gen/ proto/*.proto`

use anyhow::Result;
use prost::Message;
use prost_types::FileDescriptorSet;
use std::path::Path;

/// Export the concatenated descriptor set from the blob catalog to a file.
///
/// The blob catalog IS the plugin set: one descriptor set per blob, concatenated
/// into one FileDescriptorSet for UI codegen. Each blob carries SECTION_DESCRIPTOR_SET
/// synthesized from PluginSchema.methods at sealing time.
pub fn export_catalog_descriptor_set(catalog_dir: &Path, output_path: &Path) -> Result<()> {
    let store = op_blob::BlobStore::open(catalog_dir)?;
    let blobs = store.plugin_object_blobs();

    let mut combined_set = FileDescriptorSet::default();
    for blob in blobs {
        if blob.descriptor_set.is_empty() {
            continue;
        }
        if let Ok(mut set) = FileDescriptorSet::decode(blob.descriptor_set.as_slice()) {
            combined_set.file.append(&mut set.file);
        }
    }

    std::fs::create_dir_all(output_path.parent().unwrap_or(Path::new(".")))?;
    let mut bytes = Vec::new();
    combined_set
        .encode(&mut bytes)
        .map_err(|e| anyhow::anyhow!("encode failed: {}", e))?;
    std::fs::write(output_path, &bytes)
        .map_err(|e| anyhow::anyhow!("write failed: {}", e))?;

    Ok(())
}

/// Get the schema catalog hash for drift detection.
///
/// The UI should embed this hash and verify it matches at runtime to detect
/// when the backend schema changed and types need regeneration.
pub fn get_catalog_hash(catalog_dir: &Path) -> Result<String> {
    let manifest_path = catalog_dir.join(".manifest.json");
    let manifest_json = std::fs::read_to_string(&manifest_path)
        .map_err(|e| anyhow::anyhow!("read manifest failed: {}", e))?;
    let manifest: serde_json::Value = serde_json::from_str(&manifest_json)
        .map_err(|e| anyhow::anyhow!("parse manifest failed: {}", e))?;
    manifest
        .get("catalog_hash")
        .and_then(|v| v.as_str())
        .map(String::from)
        .ok_or_else(|| anyhow::anyhow!("catalog_hash not found in manifest"))
}

