// OD-32: Export concatenated FileDescriptorSet from blob catalog for UI codegen
fn export_descriptors(catalog_dir: &Path, output: &Path) -> Result<(), String> {
    let cat = ActiveReflectionCatalog::open(catalog_dir).map_err(|e| e.to_string())?;
    let blobs: Vec<PluginObjectBlob> = cat.plugin_object_blobs();

    let mut combined_set = FileDescriptorSet::default();
    for blob in blobs {
        if blob.descriptor_set.is_empty() {
            continue;
        }
        if let Ok(mut set) = FileDescriptorSet::decode(blob.descriptor_set.as_slice()) {
            combined_set.file.append(&mut set.file);
        }
    }

    std::fs::create_dir_all(output.parent().unwrap_or(Path::new("."))).map_err(|e| e.to_string())?;
    let mut bytes = Vec::new();
    combined_set.encode(&mut bytes).map_err(|e| format!("encode failed: {}", e))?;
