    println!("exported {} descriptor files from {} to {}", combined_set.file.len(), catalog_dir.display(), output.display());

    // Also output the catalog hash for UI drift detection
    let hash = cat.catalog_hash();
    println!("catalog-hash  {}", hash);
    Ok(())
}

