  string plugin_id = 3 [(validate.rules).string = {
    pattern: "^[a-z][a-z0-9_-]*$",
    min_len: 1,
    max_len: 64
  }];

  // D-Bus object path
  string object_path = 4 [(validate.rules).string = {
    pattern: "^/[a-zA-Z0-9_/-]+$",
    min_len: 1,
    max_len: 256
  }];

  // Change type
  ChangeType change_type = 5 [(validate.rules).enum = {defined_only: true}];

  // Property/method name (if applicable)
  string member_name = 6 [(validate.rules).string = {max_len: 128}];

  // Previous value (for updates)
  google.protobuf.Value old_value = 7;

  // New value
  google.protobuf.Value new_value = 8;

  // Tags touched by this change
  repeated string tags_touched = 9 [(validate.rules).repeated = {
    max_items: 10,
    items: {string: {pattern: "^[a-zA-Z0-9_-]+$", max_len: 32}}
  }];

  // Event hash for verification
  string event_hash = 10 [(validate.rules).string = {
    pattern: "^[a-f0-9]{64}$"
  }];

  // Timestamp
  google.protobuf.Timestamp timestamp = 11;

  // Actor who made the change
  string actor_id = 12 [(validate.rules).string = {
    pattern: "^[a-zA-Z0-9@._-]+$",
    max_len: 128
  }];
}
enum ChangeType {
  CHANGE_TYPE_UNSPECIFIED = 0;
  CHANGE_TYPE_PROPERTY_SET = 1;
  CHANGE_TYPE_PROPERTY_DELETE = 2;
  CHANGE_TYPE_METHOD_CALL = 3;
  CHANGE_TYPE_SIGNAL = 4;
  CHANGE_TYPE_OBJECT_ADDED = 5;
  CHANGE_TYPE_OBJECT_REMOVED = 6;
  CHANGE_TYPE_SCHEMA_MIGRATION = 7;
