  string plugin_id = 1 [(validate.rules).string = {
    pattern: "^[a-z][a-z0-9_-]*$",
    min_len: 1,
    max_len: 64
  }];

  // D-Bus object path
  string object_path = 2 [(validate.rules).string = {
    pattern: "^/[a-zA-Z0-9_/-]+$",
    min_len: 1,
    max_len: 256
  }];

  // Operation type
  OperationType operation = 3 [(validate.rules).enum = {defined_only: true}];

  // Member (property or method name)
  string member_name = 4 [(validate.rules).string = {
    pattern: "^[a-zA-Z_][a-zA-Z0-9_]*$",
    min_len: 1,
    max_len: 128
  }];

