  }];

  // Capability ID for authorization
  string capability_id = 7 [(validate.rules).string = {
    pattern: "^[a-z][a-z0-9_-]*$",
    max_len: 64
  }];

  // Idempotency key
  string idempotency_key = 8 [(validate.rules).string = {
    pattern: "^[a-f0-9]{32}$"
  }];

